package webui

import (
	"errors"
	"fmt"
	"net"
	"net/http"
	"strconv"
	"strings"
)

type hostPolicy struct {
	port           string
	explicit       map[string]bool
	allowLiteralIP bool
}

func authority(raw string) (host, port string, err error) {
	if raw == "" || strings.ContainsAny(raw, "/\\@#? \t\r\n") {
		return "", "", fmt.Errorf("invalid Host")
	}
	host, port, err = net.SplitHostPort(raw)
	if err != nil {
		host = strings.Trim(raw, "[]")
		port = ""
		if strings.Contains(host, ":") && net.ParseIP(host) == nil {
			return "", "", fmt.Errorf("invalid Host")
		}
	}
	host = strings.ToLower(strings.TrimSuffix(host, "."))
	if host == "" {
		return "", "", fmt.Errorf("empty Host")
	}
	if port != "" {
		if n, e := strconv.Atoi(port); e != nil || n < 1 || n > 65535 {
			return "", "", fmt.Errorf("invalid Host port")
		}
	}
	return host, port, nil
}

func hostKey(host, port string) string { return host + "\x00" + port }

// ConfigureListener binds accepted authorities to the real listener. Extra
// authorities are explicit proxy/domain choices; forwarded headers are ignored.
// Configure once before serving requests. NewServer alone accepts loopback only.
func (s *Server) ConfigureListener(addr string, extra []string) error {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return err
	}
	policy := &hostPolicy{port: port, explicit: map[string]bool{}}
	ip := net.ParseIP(host)
	policy.allowLiteralIP = host == "" || (ip != nil && ip.IsUnspecified())
	if host != "" && !policy.allowLiteralIP {
		policy.explicit[hostKey(strings.ToLower(host), port)] = true
	}
	for _, raw := range extra {
		h, p, err := authority(raw)
		if err != nil {
			return fmt.Errorf("allow-host %q: %w", raw, err)
		}
		policy.explicit[hostKey(h, p)] = true
	}
	s.hosts = policy
	return nil
}

func (s *Server) hostGuard(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		h, p, err := authority(r.Host)
		if err != nil {
			http.Error(w, "Host rejected", http.StatusForbidden)
			return
		}
		policy := s.hosts
		allowed := false
		if policy != nil && policy.explicit[hostKey(h, p)] {
			allowed = true
		}
		portOK := policy == nil || policy.port == "" || p == policy.port
		ip := net.ParseIP(h)
		if portOK && (h == "localhost" || (ip != nil && ip.IsLoopback())) {
			allowed = true
		}
		if policy != nil && policy.allowLiteralIP && portOK && ip != nil {
			allowed = true
		}
		if !allowed {
			http.Error(w, "Host rejected; configure --allow-host for a trusted domain or proxy", http.StatusForbidden)
			return
		}
		w.Header().Set("X-Content-Type-Options", "nosniff")
		w.Header().Set("Referrer-Policy", "same-origin")
		next.ServeHTTP(w, r)
	})
}

func bodyLimit(path string) int64 {
	switch {
	case strings.HasPrefix(path, "/edit/"):
		return 1 << 20
	case strings.HasPrefix(path, "/task/"):
		return 64 << 10
	case path == "/login" || path == "/setup":
		return 8 << 10
	default:
		return 16 << 10
	}
}

func (s *Server) requestLimits(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			r.Body = http.MaxBytesReader(w, r.Body, bodyLimit(r.URL.Path))
			var err error
			if strings.HasPrefix(r.Header.Get("Content-Type"), "multipart/form-data") {
				err = r.ParseMultipartForm(64 << 10)
				if r.MultipartForm != nil {
					defer r.MultipartForm.RemoveAll()
				}
			} else {
				err = r.ParseForm()
			}
			if err != nil {
				var max *http.MaxBytesError
				status := http.StatusBadRequest
				if errors.As(err, &max) {
					status = http.StatusRequestEntityTooLarge
				}
				http.Error(w, "invalid or oversized form", status)
				return
			}
		}
		if r.URL.Path == "/search" || r.URL.Path == "/api/search" {
			select {
			case s.searchSlots <- struct{}{}:
				defer func() { <-s.searchSlots }()
			default:
				w.Header().Set("Retry-After", "1")
				http.Error(w, "search queue busy", http.StatusServiceUnavailable)
				return
			}
		}
		next.ServeHTTP(w, r)
	})
}

package webui

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"golang.org/x/crypto/bcrypt"

	"github.com/neutrospec/canopy/internal/config"
)

// Auth errors carried as sentinels so the HTTP handler can localize them
// (the store layer has no locale); see docs/web-ui-i18n.md.
var (
	errBadSetupCode = errors.New("bad setup code")
	errBadCreds     = errors.New("bad credentials")
)

// Auth protects non-loopback serving (docs/web-ui-plan-2.md D1/D2).
// One account, bootstrapped by a one-time setup code that is printed
// to the terminal only — whoever operates the server registers the
// credentials, so a public bind can never be claimed by a stranger.

const (
	sessionCookie = "canopy_session"
	sessionTTL    = 30 * 24 * time.Hour
	maxLoginDelay = 16 * time.Second
)

type account struct {
	ID   string `json:"id"`
	Hash string `json:"hash"` // bcrypt
}

type authStore struct {
	path string

	mu        sync.Mutex
	acct      *account
	setupCode string
	sessions  map[string]time.Time // token -> expiry
	failures  int
}

// webAuthPath is ~/.config/canopy/webauth.json — outside the wiki so
// credentials never travel through git.
func webAuthPath() string {
	return filepath.Join(config.ConfigHome(), "webauth.json")
}

func loadAuthStore(path string) (*authStore, error) {
	a := &authStore{path: path, sessions: map[string]time.Time{}}
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return a, nil
	}
	if err != nil {
		return nil, err
	}
	var acct account
	if err := json.Unmarshal(data, &acct); err != nil {
		return nil, fmt.Errorf("%s is corrupt (delete it to re-run setup): %w", path, err)
	}
	if acct.ID != "" && acct.Hash != "" {
		a.acct = &acct
	}
	return a, nil
}

func randomToken(bytes int) string {
	b := make([]byte, bytes)
	if _, err := rand.Read(b); err != nil {
		panic(err) // crypto/rand failure is not recoverable
	}
	return hex.EncodeToString(b)
}

func (a *authStore) hasAccount() bool {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.acct != nil
}

// issueSetupCode creates (once) and returns the one-time setup code.
func (a *authStore) issueSetupCode() string {
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.setupCode == "" {
		a.setupCode = randomToken(4) // 8 hex chars, single-use, terminal-only
	}
	return a.setupCode
}

// register creates the single account. Requires the setup code.
func (a *authStore) register(code, id, pw string) error {
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.acct != nil {
		return fmt.Errorf("account already exists")
	}
	if a.setupCode == "" || subtle.ConstantTimeCompare([]byte(code), []byte(a.setupCode)) != 1 {
		return errBadSetupCode
	}
	if len(id) < 1 || len(pw) < 8 {
		return errBadCreds
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	if err != nil {
		return err
	}
	acct := &account{ID: id, Hash: string(hash)}
	data, err := json.MarshalIndent(acct, "", "  ")
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(a.path), 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(a.path, data, 0o600); err != nil {
		return err
	}
	a.acct = acct
	a.setupCode = "" // single use
	return nil
}

// login verifies credentials with an escalating delay on failures.
func (a *authStore) login(id, pw string) bool {
	a.mu.Lock()
	acct, failures := a.acct, a.failures
	a.mu.Unlock()
	if failures > 0 {
		d := time.Second << (failures - 1)
		if d > maxLoginDelay {
			d = maxLoginDelay
		}
		time.Sleep(d)
	}
	ok := acct != nil &&
		subtle.ConstantTimeCompare([]byte(id), []byte(acct.ID)) == 1 &&
		bcrypt.CompareHashAndPassword([]byte(acct.Hash), []byte(pw)) == nil
	a.mu.Lock()
	defer a.mu.Unlock()
	if ok {
		a.failures = 0
	} else if a.failures < 10 {
		a.failures++
	}
	return ok
}

func (a *authStore) newSession() string {
	a.mu.Lock()
	defer a.mu.Unlock()
	tok := randomToken(32)
	a.sessions[tok] = time.Now().Add(sessionTTL)
	return tok
}

func (a *authStore) validSession(tok string) bool {
	a.mu.Lock()
	defer a.mu.Unlock()
	exp, ok := a.sessions[tok]
	if !ok {
		return false
	}
	if time.Now().After(exp) {
		delete(a.sessions, tok)
		return false
	}
	return true
}

func (a *authStore) dropSession(tok string) {
	a.mu.Lock()
	defer a.mu.Unlock()
	delete(a.sessions, tok)
}

// --- server integration ---

// EnableAuth turns on the auth requirement (non-loopback bind). When
// no account exists yet it returns the one-time setup code to print.
func (s *Server) EnableAuth() (setupCode string, err error) {
	a, err := loadAuthStore(webAuthPath())
	if err != nil {
		return "", err
	}
	s.auth = a
	s.authRequired = true
	if !a.hasAccount() {
		return a.issueSetupCode(), nil
	}
	return "", nil
}

// IsLoopbackAddr reports whether a listen address binds only loopback.
// An empty host ("":8737") binds every interface — not loopback.
func IsLoopbackAddr(addr string) bool {
	host, _, err := net.SplitHostPort(addr)
	if err != nil || host == "" {
		return false
	}
	if strings.EqualFold(host, "localhost") {
		return true
	}
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

func (s *Server) sessionOK(r *http.Request) bool {
	c, err := r.Cookie(sessionCookie)
	return err == nil && s.auth.validSession(c.Value)
}

// guard wraps the mux with the auth wall and a same-origin check on
// every mutating request (CSRF/DNS-rebinding defence — applies even on
// localhost, where a hostile web page could otherwise POST blindly).
func (s *Server) guard(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			if o := r.Header.Get("Origin"); o != "" {
				if u, err := url.Parse(o); err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.User != nil || !strings.EqualFold(u.Host, r.Host) || u.Path != "" || u.RawQuery != "" || u.Fragment != "" {
					http.Error(w, "cross-origin request rejected", http.StatusForbidden)
					return
				}
			}
		}
		if !s.authRequired {
			next.ServeHTTP(w, r)
			return
		}
		p := r.URL.Path
		if strings.HasPrefix(p, "/static/") || p == "/login" || p == "/setup" {
			next.ServeHTTP(w, r)
			return
		}
		if s.sessionOK(r) {
			next.ServeHTTP(w, r)
			return
		}
		if strings.HasPrefix(p, "/api/") {
			w.Header().Set("Content-Type", "application/json; charset=utf-8")
			w.WriteHeader(http.StatusUnauthorized)
			json.NewEncoder(w).Encode(map[string]any{"error": "authentication_required"})
			return
		}
		if !s.auth.hasAccount() {
			http.Redirect(w, r, "/setup", http.StatusFound)
			return
		}
		http.Redirect(w, r, "/login", http.StatusFound)
	})
}

func (s *Server) setSession(w http.ResponseWriter) {
	http.SetCookie(w, &http.Cookie{
		Name:     sessionCookie,
		Value:    s.auth.newSession(),
		Path:     "/",
		HttpOnly: true,
		SameSite: http.SameSiteLaxMode,
		MaxAge:   int(sessionTTL / time.Second),
	})
}

// --- handlers ---

func (s *Server) handleSetupForm(w http.ResponseWriter, r *http.Request) {
	if !s.authRequired || s.auth.hasAccount() {
		http.Redirect(w, r, "/", http.StatusFound)
		return
	}
	s.render(w, r, http.StatusOK, "setup.html", map[string]any{"Title": localizeString(s.loc(r), "title_setup")})
}

func (s *Server) handleSetupSave(w http.ResponseWriter, r *http.Request) {
	if !s.authRequired || s.auth.hasAccount() {
		http.Redirect(w, r, "/", http.StatusFound)
		return
	}
	err := s.auth.register(
		strings.TrimSpace(r.FormValue("code")),
		strings.TrimSpace(r.FormValue("id")),
		r.FormValue("password"),
	)
	if err != nil {
		loc := s.loc(r)
		msg := err.Error()
		switch {
		case errors.Is(err, errBadSetupCode):
			msg = localizeString(loc, "auth_bad_code")
		case errors.Is(err, errBadCreds):
			msg = localizeString(loc, "auth_bad_creds")
		}
		s.render(w, r, http.StatusBadRequest, "setup.html", map[string]any{"Title": localizeString(loc, "title_setup"), "Error": msg})
		return
	}
	s.setSession(w)
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

func (s *Server) handleLoginForm(w http.ResponseWriter, r *http.Request) {
	if !s.authRequired || s.sessionOK(r) {
		http.Redirect(w, r, "/", http.StatusFound)
		return
	}
	if !s.auth.hasAccount() {
		http.Redirect(w, r, "/setup", http.StatusFound)
		return
	}
	s.render(w, r, http.StatusOK, "login.html", map[string]any{"Title": localizeString(s.loc(r), "title_login")})
}

func (s *Server) handleLoginSubmit(w http.ResponseWriter, r *http.Request) {
	if !s.authRequired {
		http.Redirect(w, r, "/", http.StatusFound)
		return
	}
	if s.auth.login(strings.TrimSpace(r.FormValue("id")), r.FormValue("password")) {
		s.setSession(w)
		http.Redirect(w, r, "/", http.StatusSeeOther)
		return
	}
	loc := s.loc(r)
	s.render(w, r, http.StatusUnauthorized, "login.html", map[string]any{
		"Title": localizeString(loc, "title_login"), "Error": localizeString(loc, "auth_login_failed"),
	})
}

func (s *Server) handleLogout(w http.ResponseWriter, r *http.Request) {
	if c, err := r.Cookie(sessionCookie); err == nil && s.auth != nil {
		s.auth.dropSession(c.Value)
	}
	http.SetCookie(w, &http.Cookie{Name: sessionCookie, Value: "", Path: "/", MaxAge: -1})
	http.Redirect(w, r, "/login", http.StatusSeeOther)
}

package webui

import (
	"bytes"
	"context"
	"embed"
	"encoding/json"
	"html/template"
	"io/fs"
	"log"
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/nicksnyder/go-i18n/v2/i18n"

	"github.com/neutrospec/canopy/internal/attention"
	"github.com/neutrospec/canopy/internal/config"
	cembed "github.com/neutrospec/canopy/internal/embed"
	"github.com/neutrospec/canopy/internal/indexer"
	"github.com/neutrospec/canopy/internal/mermaid"
	"github.com/neutrospec/canopy/internal/reads"
	"github.com/neutrospec/canopy/internal/resurface"
	"github.com/neutrospec/canopy/internal/search"
	"github.com/neutrospec/canopy/internal/store"
	"github.com/neutrospec/canopy/internal/tasks"
	"github.com/neutrospec/canopy/internal/wiki"
)

//go:embed templates/* static/*
var assets embed.FS

// Server renders the wiki read-only over HTTP. The engine may be nil,
// in which case search degrades to keyword-only (same as the CLI).
type Server struct {
	w   *config.Wiki
	eng cembed.Engine
	mu  sync.Mutex // serializes this server's explicit/automatic read updates
	// tmpl is keyed by locale then template name: each locale gets its own
	// parsed set with `t` bound to that locale's localizer (html/template
	// binds funcs at parse time). See docs/web-ui-i18n.md.
	tmpl map[string]map[string]*template.Template
	i18n *i18nBundle

	auth         *authStore
	authRequired bool
	hosts        *hostPolicy
	searchSlots  chan struct{}
	indexSlot    chan struct{}
	staticTags   map[string]string

	dailyMu sync.Mutex
	daily   daily
}

var pageTemplates = []string{"home.html", "page.html", "search.html", "browse.html", "recent.html", "attention.html", "edit.html", "login.html", "setup.html", "discover.html", "gaps.html", "graph.html", "history.html", "tasks.html"}

func NewServer(w *config.Wiki, eng cembed.Engine) (*Server, error) {
	ib, err := loadBundle()
	if err != nil {
		return nil, err
	}
	s := &Server{w: w, eng: eng, i18n: ib, tmpl: map[string]map[string]*template.Template{}, searchSlots: make(chan struct{}, 8), indexSlot: make(chan struct{}, 1)}
	s.staticTags = map[string]string{}
	if err := fs.WalkDir(assets, "static", func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() {
			return nil
		}
		data, err := assets.ReadFile(path)
		if err != nil {
			return err
		}
		s.staticTags["/"+path] = `"` + contentHash(data) + `"`
		return nil
	}); err != nil {
		return nil, err
	}
	s.staticTags["/static/vendor/mermaid.min.js"] = `"` + contentHash(mermaid.Bundle) + `"`
	for _, lang := range ib.langs {
		loc := ib.localizer(lang)
		funcs := template.FuncMap{"short": short, "pathref": url.PathEscape, "assetURL": assetURL, "pageURL": func(ref string) string { return "/page/" + url.PathEscape(ref) }}
		for k, v := range i18nFuncMap(loc) {
			funcs[k] = v
		}
		set := map[string]*template.Template{}
		for _, name := range pageTemplates {
			t, err := template.New("base.html").Funcs(funcs).ParseFS(assets, "templates/base.html", "templates/"+name)
			if err != nil {
				return nil, err
			}
			set[name] = t
		}
		s.tmpl[lang] = set
	}
	return s, nil
}

// loc returns the localizer for the request's resolved locale — for Go
// handlers that build dynamic display strings (invariant M: dynamic strings
// are localized where the data lives, static labels in templates via {{t}}).
func (s *Server) loc(r *http.Request) *i18n.Localizer {
	return s.i18n.localizer(s.i18n.resolveLang(r))
}

func (s *Server) Handler() http.Handler {
	mux := http.NewServeMux()
	staticFiles := http.FileServerFS(assets)
	mux.Handle("GET /static/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "no-cache")
		if tag := s.staticTags[r.URL.Path]; tag != "" {
			w.Header().Set("ETag", tag)
		}
		staticFiles.ServeHTTP(w, r)
	}))
	// The mermaid bundle lives in internal/mermaid (which validates wiki
	// diagrams with it); serving that same copy keeps parser and renderer
	// in lockstep (invariant P3). More specific pattern wins over /static/.
	mux.HandleFunc("GET /static/vendor/mermaid.min.js", func(rw http.ResponseWriter, r *http.Request) {
		rw.Header().Set("Content-Type", "text/javascript; charset=utf-8")
		rw.Header().Set("Cache-Control", "no-cache")
		rw.Header().Set("ETag", s.staticTags["/static/vendor/mermaid.min.js"])
		http.ServeContent(rw, r, "mermaid.min.js", time.Time{}, bytes.NewReader(mermaid.Bundle))
	})
	mux.HandleFunc("GET /page/{slug}", s.handlePage)
	mux.HandleFunc("GET /search", s.handleSearch)
	mux.HandleFunc("GET /api/search", s.handleAPISearch)
	mux.HandleFunc("GET /api/preview/{slug}", s.handleAPIPreview)
	mux.HandleFunc("GET /edit/{slug}", s.handleEditForm)
	mux.HandleFunc("POST /edit/{slug}", s.handleEditSave)
	mux.HandleFunc("GET /browse", s.handleBrowse)
	mux.HandleFunc("GET /tag/{tag}", s.handleTag)
	mux.HandleFunc("GET /special/recent", s.handleRecent)
	mux.HandleFunc("GET /special/attention", s.handleAttention)
	mux.HandleFunc("GET /special/random", s.handleRandom)
	mux.HandleFunc("GET /graph", s.handleGraphPage)
	mux.HandleFunc("GET /api/graph", s.handleAPIGraph)
	mux.HandleFunc("GET /history", s.handleHistory)
	mux.HandleFunc("GET /special/discover", s.handleDiscover)
	mux.HandleFunc("GET /special/gaps", s.handleGaps)
	mux.HandleFunc("POST /read/{slug}", s.handleReadMark)
	mux.HandleFunc("POST /api/read/{slug}", s.handleReadAuto)
	mux.HandleFunc("POST /resurface/feedback", s.handleResurfaceFeedback)
	mux.HandleFunc("POST /task/connect", s.handleTaskConnect)
	mux.HandleFunc("POST /task/edit/{slug}", s.handleTaskEdit)
	mux.HandleFunc("POST /task/cancel/{id}", s.handleTaskCancel)
	mux.HandleFunc("GET /special/tasks", s.handleTasksPage)
	mux.HandleFunc("GET /setup", s.handleSetupForm)
	mux.HandleFunc("POST /setup", s.handleSetupSave)
	mux.HandleFunc("GET /login", s.handleLoginForm)
	mux.HandleFunc("POST /login", s.handleLoginSubmit)
	mux.HandleFunc("POST /logout", s.handleLogout)
	mux.HandleFunc("GET /setlang", s.handleSetLang)
	mux.HandleFunc("GET /{$}", s.handleHome)
	return logRequests(s.hostGuard(s.guard(s.requestLimits(mux))))
}

// assetURL changes with the exact embedded bytes, so a same-origin upgrade
// cannot reuse stale application CSS/JS under an unchanged URL.
func assetURL(path string) string {
	data, err := assets.ReadFile(strings.TrimPrefix(path, "/"))
	if err != nil {
		return path
	}
	return path + "?v=" + contentHash(data)[:12]
}

func logRequests(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		next.ServeHTTP(w, r)
		log.Printf("%s %s", r.Method, r.URL)
	})
}

func (s *Server) render(w http.ResponseWriter, r *http.Request, status int, name string, data any) {
	lang := s.i18n.resolveLang(r)
	if m, ok := data.(map[string]any); ok {
		m["AuthOn"] = s.authRequired
		// Language-selector data for base.html (invariant M4: the loaded
		// locale list drives the menu, so a new file just appears).
		m["Lang"] = lang
		m["LangName"] = endonym(lang)
		m["Langs"] = s.i18n.options()
		m["Path"] = r.URL.RequestURI()
		m["View"] = strings.TrimSuffix(name, ".html")
		m["ActiveNav"] = activeNav(name)
		messages := map[string]string{}
		lc := s.i18n.localizer(lang)
		for _, id := range clientMessageIDs {
			messages[id] = localizeString(lc, id)
		}
		// html/template serializes this map in the JSON script context,
		// including escaping any HTML embedded in translations.
		m["ClientMessages"] = messages
	}
	set := s.tmpl[lang]
	if set == nil {
		set = s.tmpl[defaultLang]
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-cache")
	w.WriteHeader(status)
	// Template-only links can disambiguate lawful slugs ending in .md by
	// using the governed path. Load the map lazily, only for such names.
	tmpl, err := set[name].Clone()
	if err != nil {
		log.Printf("template clone: %v", err)
		return
	}
	var refs *wiki.ScanResult
	var refsOnce sync.Once
	tmpl = tmpl.Funcs(template.FuncMap{"pageURL": func(ref string) string {
		if strings.HasSuffix(strings.ToLower(ref), ".md") {
			refsOnce.Do(func() { refs, _ = wiki.Scan(s.w) })
			if refs != nil {
				if p := refs.BySlug[strings.ToLower(ref)]; p != nil {
					return pagePath(p)
				}
			}
		}
		return "/page/" + url.PathEscape(ref)
	}})
	if err := tmpl.ExecuteTemplate(w, "base.html", data); err != nil {
		log.Printf("template %s: %v", name, err)
	}
}

var clientMessageIDs = []string{
	"copy_button", "copy_done", "copy_failed", "heading_link", "page_toc_title",
	"page_read_label", "page_auto", "page_reread", "page_reread_title",
	"page_cancel", "page_unread_title", "graph_links", "graph_touches",
	"graph_legend_unread", "graph_legend_island", "graph_load_failed", "graph_status_unknown", "graph_available_touches", "reads_partial",
	"page_read_failed", "page_read_auth", "diagram_failed", "math_failed",
}

func activeNav(name string) string {
	switch name {
	case "page.html", "edit.html":
		return "browse"
	case "gaps.html":
		return "attention"
	default:
		return strings.TrimSuffix(name, ".html")
	}
}

// handleSetLang is the language selector: set the lang cookie and return to
// the page the user was on (the one new setting, docs/web-ui-i18n.md).
func (s *Server) handleSetLang(w http.ResponseWriter, r *http.Request) {
	lang := r.URL.Query().Get("lang")
	if !s.i18n.has(lang) {
		lang = defaultLang
	}
	http.SetCookie(w, &http.Cookie{Name: langCookie, Value: lang, Path: "/", MaxAge: 86400 * 365, HttpOnly: true, SameSite: http.SameSiteLaxMode})
	next := r.URL.Query().Get("next")
	if next == "" || !strings.HasPrefix(next, "/") || strings.HasPrefix(next, "//") || strings.ContainsAny(next, "\\\r\n") {
		next = "/"
	}
	http.Redirect(w, r, next, http.StatusSeeOther)
}

func (s *Server) fail(w http.ResponseWriter, err error) {
	log.Printf("error: %v", err)
	http.Error(w, err.Error(), http.StatusInternalServerError)
}

// --- home ---

type dirStat struct {
	Dir   string
	Count int
	Read  int // read pages in this dir — fills its canopy-band segment
	Pct   int // read percentage within the dir
}

func (s *Server) handleHome(w http.ResponseWriter, r *http.Request) {
	scan, err := wiki.Scan(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	vectors, current, indexErr := s.currentVectors(r.Context(), scan)
	if indexErr != nil {
		log.Printf("home index: %v", indexErr)
	}
	rs, readErr := reads.Load(s.w)
	if readErr != nil {
		log.Printf("home reads: %v", readErr)
	}
	now := time.Now()
	byDir := map[string]int{}
	readByDir := map[string]int{}
	readTotal := 0
	for _, p := range scan.Pages {
		byDir[p.Dir]++
		if rs.IsRead(p.Slug) {
			readByDir[p.Dir]++
			readTotal++
		}
	}
	var dirs []dirStat
	for _, d := range s.w.Cfg.Schema.PageDirs {
		st := dirStat{Dir: d, Count: byDir[d], Read: readByDir[d]}
		if st.Count > 0 {
			st.Pct = st.Read * 100 / st.Count
		}
		dirs = append(dirs, st)
	}

	// 오늘의 주의: distinct pages touched and searches asked today,
	// from the local event log (best-effort).
	todayPages, todaySearches := 0, 0
	if ev, err := attention.Open(s.w.AttentionDBPath()); err == nil {
		// AttnOnly: lifecycle events (task/sync) are not attention (N3).
		if events, err := ev.Query(attention.Filter{Limit: 400, AttnOnly: true}); err == nil {
			day := now.Format("2006-01-02")
			seen := map[string]bool{}
			for _, e := range events {
				t, err := time.Parse(time.RFC3339, e.TS)
				if err != nil || t.Local().Format("2006-01-02") != day {
					continue
				}
				if e.Kind == attention.KindSearch {
					todaySearches++
				} else if !seen[e.Slug] {
					seen[e.Slug] = true
					todayPages++
				}
			}
		}
		ev.Close()
	}

	recent := append([]*wiki.Page(nil), scan.Pages...)
	sort.Slice(recent, func(i, j int) bool { return recent[i].Updated > recent[j].Updated })
	if len(recent) > 10 {
		recent = recent[:10]
	}
	// Locale-dependent display strings are built here, where the data is,
	// and passed in finished (docs/web-ui-i18n.md); static labels use {{t}}.
	lc := s.loc(r)
	discover := s.discoverRanked(scan, rs, vectors, now, lc)
	if len(discover) > 4 {
		discover = discover[:4]
	}
	var pick *resurface.Pick
	var bridge *resurface.Bridge
	if r.Method != http.MethodHead && readErr == nil {
		pick, bridge = s.todaysCard(scan, rs, vectors)
	}
	pendingCount, tasksErr := tasks.PendingCount(s.w)
	if tasksErr != nil {
		log.Printf("home task summary: %v", tasksErr)
	}

	date := now.Format("2006-01-02") + " (" + localizeString(lc, "wd_"+strconv.Itoa(int(now.Weekday()))) + ")"
	readProgress := localizeString(lc, "home_read_progress", "Read", readTotal, "Total", len(scan.Pages))
	todayLine := ""
	if todayPages > 0 || todaySearches > 0 {
		var parts []string
		if todayPages > 0 {
			parts = append(parts, localizeString(lc, "home_today_pages", "Count", todayPages))
		}
		if todaySearches > 0 {
			parts = append(parts, localizeString(lc, "home_today_searches", "Count", todaySearches))
		}
		todayLine = localizeString(lc, "home_today", "Detail", strings.Join(parts, " · "))
	}

	s.render(w, r, http.StatusOK, "home.html", map[string]any{
		"Title":             localizeString(lc, "nav_home"),
		"Date":              date,
		"Total":             len(scan.Pages),
		"ReadTotal":         readTotal,
		"UnreadTotal":       len(scan.Pages) - readTotal,
		"ReadAvailable":     rs.HumanAvailable(),
		"ReadsPartial":      readErr != nil,
		"SemanticAvailable": indexErr == nil && current != nil && current.SemanticReady,
		"PendingCount":      pendingCount,
		"TasksAvailable":    tasksErr == nil,
		"Dirs":              dirs,
		"ReadProgress":      readProgress,
		"TodayLine":         todayLine,
		"Recent":            recent,
		"Discover":          discover,
		"Pick":              pick,
		"Bridge":            bridge,
	})
}

// --- page view ---

func (s *Server) handlePage(w http.ResponseWriter, r *http.Request) {
	scan, err := wiki.Scan(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	vectors, current, indexErr := s.currentVectors(r.Context(), scan)
	if indexErr != nil {
		log.Printf("page suggestions: %v", indexErr)
	}
	p, err := scan.Find(r.PathValue("slug"))
	if err != nil {
		// Wikipedia pattern: a missing page is a search, not a dead end.
		s.searchFallback(w, r, r.PathValue("slug"))
		return
	}
	body, err := RenderPageWithResolver(p.Body, func(target string) (string, string, bool) {
		linked, err := scan.Find(target)
		if err != nil {
			return wiki.NormalizeLink(target), target, false
		}
		reference := linked.Slug
		if strings.HasSuffix(strings.ToLower(reference), ".md") {
			reference = linked.RelPath
		}
		return strings.ToLower(linked.Slug), reference, true
	})
	if err != nil {
		s.fail(w, err)
		return
	}
	slug := strings.ToLower(p.Slug)
	backlinks := scan.Backlinks()[slug]
	nodes, edges := localGraph(scan, p, backlinks)
	rs, readErr := reads.Load(s.w)
	if readErr != nil {
		log.Printf("page reads: %v", readErr)
	}
	// A page open is exposure-plus, not a read (원칙 12): it goes to the
	// machine-local event log only, never into the read aggregates.
	s.logEvent(slug, attention.KindView, "")
	var agentDays int
	if a := rs.Agent[slug]; a != nil {
		agentDays = a.Days
	}
	// Per-page attention panel (M12): recent trail + 12-week sparkline
	// from the local event log, best-effort.
	lc := s.loc(r)
	var attnRecent []histEntry
	var spark template.HTML
	if ev, err := attention.Open(s.w.AttentionDBPath()); err == nil {
		if events, err := ev.BySlug(slug, 6); err == nil {
			for _, e := range events {
				attnRecent = append(attnRecent, histEntryOf(e, "2006-01-02", lc))
			}
		}
		if counts, err := ev.WeeklyCounts(slug, 12, time.Now()); err == nil {
			spark = sparkSVG(counts, localizeString(lc, "spark_aria"))
		}
		ev.Close()
	}
	// Delegated-task wiring (docs/agent-tasks.md): pending tasks show as
	// the page's todo list, and suggestions with a filed connect task
	// swap their button for a "requested" marker.
	pageTasks, filed, tasksErr := s.pageTasks(slug, lc)
	if tasksErr != nil {
		log.Printf("page task summary: %v", tasksErr)
	}
	suggested := s.suggestLinks(scan, p, backlinks, vectors)
	for i := range suggested {
		suggested[i].Requested = filed[strings.ToLower(suggested[i].Slug)]
	}
	var receipt *tasks.Task
	if id := r.URL.Query().Get("tasked"); id != "" {
		if task, err := tasks.Get(s.w, id); err == nil && task.Involves(slug) {
			receipt = task
		}
	}
	receiptStatus := ""
	if receipt != nil {
		receiptStatus = taskStatusLabel(lc, receipt.Status)
	}
	s.render(w, r, http.StatusOK, "page.html", map[string]any{
		"Title":             p.Title,
		"Page":              p,
		"Body":              body,
		"Backlinks":         backlinks,
		"GraphNodes":        nodes,
		"GraphEdges":        edges,
		"Read":              rs.Get(slug),
		"ReadAvailable":     rs.HumanAvailable(),
		"AgentAvailable":    rs.AgentAvailable(),
		"ReadsPartial":      readErr != nil,
		"SemanticAvailable": indexErr == nil && current != nil && current.SemanticReady,
		"ReadAgo":           readAgo(rs.Get(slug), time.Now(), lc),
		"AgentDays":         agentDays,
		"AttnRecent":        attnRecent,
		"Spark":             spark,
		"ReadSecs":          readThresholdSecs(p),
		"Suggested":         suggested,
		"Tasks":             pageTasks,
		"TasksAvailable":    tasksErr == nil,
		"TaskReceipt":       receipt,
		"TaskReceiptStatus": receiptStatus,
	})
}

// readAgo renders "when did I last read this" for the page header:
// 오늘 / 어제 / N일 전.
func readAgo(r *reads.Read, now time.Time, loc *i18n.Localizer) string {
	if r == nil {
		return ""
	}
	t, err := time.Parse(time.RFC3339, r.Last)
	if err != nil {
		return ""
	}
	days := int(now.Sub(t).Hours() / 24)
	switch {
	case days <= 0:
		return localizeString(loc, "readago_today")
	case days == 1:
		return localizeString(loc, "readago_yesterday")
	default:
		return localizeString(loc, "readago_days", "Days", days)
	}
}

// logEvent appends a web-door access event to the machine-local log,
// best-effort: the event DB enriches instruments (web-ui-plan-4.md) but
// must never break page serving.
func (s *Server) logEvent(slug, kind, meta string) {
	ev, err := attention.Open(s.w.AttentionDBPath())
	if err != nil {
		return
	}
	defer ev.Close()
	ev.Log(time.Now(), slug, attention.DoorWeb, kind, meta)
}

// readThresholdSecs scales the auto-read dwell requirement with page
// length: floor 30s, +1s per 8 lines, capped at 150s.
func readThresholdSecs(p *wiki.Page) int {
	secs := 30 + p.Lines/8
	if secs > 150 {
		secs = 150
	}
	return secs
}

// --- search ---

type result struct {
	Slug    string
	Title   string
	Score   float64
	Snippet string
	URL     string
}

// withCurrentIndex serializes access without making canceled requests wait on
// a mutex and then start inference. The queue has a separate bounded budget;
// native work already running can outlive cancellation until its next boundary.
func (s *Server) withCurrentIndex(ctx context.Context, scan *wiki.ScanResult, use func(context.Context, *store.Store, *indexer.Result) error) error {
	queued, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	select {
	case s.indexSlot <- struct{}{}:
	case <-queued.Done():
		return queued.Err()
	}
	defer func() { <-s.indexSlot }()
	if err := queued.Err(); err != nil {
		return err
	}
	work, stop := context.WithTimeout(ctx, 30*time.Second)
	defer stop()
	st, err := store.Open(s.w.DBPath())
	if err != nil {
		return err
	}
	defer st.Close()
	current, err := indexer.EnsureCurrentContext(work, s.w, st, scan, s.eng, nil)
	if err != nil {
		return err
	}
	if err := work.Err(); err != nil {
		return err
	}
	return use(work, st, current)
}

// currentVectors is the shared evidence boundary for discovery, bridges, and
// suggestions. An incomplete/profile-stale corpus must not masquerade as a
// complete semantic ranking; non-vector discovery signals still work.
func (s *Server) currentVectors(ctx context.Context, scan *wiki.ScanResult) (map[string][]float32, *indexer.Result, error) {
	var vectors map[string][]float32
	var current *indexer.Result
	err := s.withCurrentIndex(ctx, scan, func(_ context.Context, st *store.Store, res *indexer.Result) error {
		current = res
		if !res.SemanticReady {
			return nil
		}
		var err error
		vectors, err = st.PageVectors()
		return err
	})
	return vectors, current, err
}

type searchOutcome struct {
	Results      []result
	Mode         string
	KeywordEmpty bool
	Index        *indexer.Result
}

func (s *Server) runSearch(ctx context.Context, query string, k int) (searchOutcome, error) {
	out := searchOutcome{Results: []result{}, Mode: "keyword"}
	scan := &wiki.ScanResult{}
	err := s.withCurrentIndex(ctx, scan, func(work context.Context, st *store.Store, current *indexer.Result) error {
		out.Index = current
		kw, err := st.SearchKeyword(query, k)
		if err != nil {
			return err
		}
		out.KeywordEmpty = len(kw) == 0
		hits := kw
		chunkText := map[string]string{}
		if s.eng != nil && current.SemanticReady {
			qv, err := cembed.EmbedContext(work, s.eng, []string{query})
			if err != nil {
				return err
			}
			sem, err := st.SearchSemantic(qv[0], k)
			if err != nil {
				return err
			}
			chunks, err := st.SearchChunks(qv[0], k*2, 1)
			if err != nil {
				return err
			}
			for _, c := range chunks {
				if _, seen := chunkText[c.Slug]; !seen {
					chunkText[c.Slug] = c.Text
				}
			}
			hits = search.Fuse(k, kw, sem)
			out.Mode = "hybrid"
		}
		for _, h := range hits {
			snippet := strings.Join(strings.Fields(h.Snippet), " ")
			if text, ok := chunkText[h.Slug]; ok {
				snippet = excerptText(text, 200)
			}
			if p, ok := scan.BySlug[strings.ToLower(h.Slug)]; ok && snippet == "" {
				snippet = FirstParagraph(p.Body, 160)
			}
			out.Results = append(out.Results, result{Slug: h.Slug, Title: h.Title, Score: h.Score, Snippet: snippet, URL: pagePath(scan.BySlug[strings.ToLower(h.Slug)])})
		}
		return work.Err()
	})
	return out, err
}

// excerptText flattens whitespace and truncates to maxRunes.
func excerptText(t string, maxRunes int) string {
	r := []rune(strings.Join(strings.Fields(t), " "))
	if len(r) > maxRunes {
		return string(r[:maxRunes]) + "…"
	}
	return string(r)
}

func (s *Server) handleSearch(w http.ResponseWriter, r *http.Request) {
	query := strings.TrimSpace(r.URL.Query().Get("q"))
	if query == "" {
		http.Redirect(w, r, "/", http.StatusFound)
		return
	}
	out, err := s.runSearch(r.Context(), query, 20)
	if err != nil {
		s.fail(w, err)
		return
	}
	// An exact slug is still a search entry point: refresh before redirecting
	// so a cold visit cannot leave cached consumers empty or stale.
	if scan, err := wiki.Scan(s.w); err == nil {
		if p, err := scan.Find(query); err == nil {
			http.Redirect(w, r, pagePath(p), http.StatusFound)
			return
		}
	}
	// The query itself is an event (search→read trail on /history);
	// the exposed hits are never marked (H5).
	s.logEvent("", attention.KindSearch, query)
	s.logSearchGap(query, out.Results, out.KeywordEmpty)
	s.render(w, r, http.StatusOK, "search.html", map[string]any{
		"Title":   localizeString(s.loc(r), "search_results_title", "Query", query),
		"Query":   query,
		"Mode":    out.Mode,
		"Results": out.Results,
		"Index":   out.Index,
	})
}

// --- JSON API (instant search + popover previews) ---

func (s *Server) emit(w http.ResponseWriter, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	if err := json.NewEncoder(w).Encode(v); err != nil {
		log.Printf("json: %v", err)
	}
}

func (s *Server) handleAPISearch(w http.ResponseWriter, r *http.Request) {
	query := strings.TrimSpace(r.URL.Query().Get("q"))
	if query == "" {
		s.emit(w, map[string]any{"results": []result{}})
		return
	}
	k := 8
	if n, err := strconv.Atoi(r.URL.Query().Get("k")); err == nil && n > 0 && n <= 50 {
		k = n
	}
	out, err := s.runSearch(r.Context(), query, k)
	if err != nil {
		s.fail(w, err)
		return
	}
	s.emit(w, map[string]any{"query": query, "mode": out.Mode, "results": out.Results, "index": out.Index})
}

func (s *Server) handleAPIPreview(w http.ResponseWriter, r *http.Request) {
	scan, err := wiki.Scan(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	p, err := scan.Find(r.PathValue("slug"))
	if err != nil {
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		w.WriteHeader(http.StatusNotFound)
		s.emit(w, map[string]any{"exists": false})
		return
	}
	s.emit(w, map[string]any{
		"exists":  true,
		"slug":    p.Slug,
		"title":   p.Title,
		"type":    p.Type,
		"excerpt": FirstParagraph(p.Body, 240),
	})
}

// searchFallback renders search results for a slug that has no page.
func (s *Server) searchFallback(w http.ResponseWriter, r *http.Request, raw string) {
	query := strings.ReplaceAll(wiki.NormalizeLink(raw), "-", " ")
	out, err := s.runSearch(r.Context(), query, 20)
	if err != nil {
		s.fail(w, err)
		return
	}
	s.render(w, r, http.StatusNotFound, "search.html", map[string]any{
		"Title":   localizeString(s.loc(r), "search_results_title", "Query", query),
		"Query":   query,
		"Mode":    out.Mode,
		"Results": out.Results,
		"Index":   out.Index,
		"Missing": raw,
	})
}

// pagePath keeps ordinary slug URLs compact and uses an encoded governed path
// when a .md suffix would otherwise be ambiguous with a filename spelling.
func pagePath(p *wiki.Page) string {
	if p == nil {
		return "/browse"
	}
	ref := p.Slug
	if strings.HasSuffix(strings.ToLower(ref), ".md") {
		ref = p.RelPath
	}
	return "/page/" + url.PathEscape(ref)
}

package webui

import (
	"crypto/sha256"
	"encoding/hex"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/neutrospec/canopy/internal/tasks"
	"github.com/neutrospec/canopy/internal/wiki"
)

// The web editor is a proposal door, not a write door (docs/agent-tasks.md
// "웹 편집 = 제안"; the 2026-07-24 위상 재평가 in web-ui-write-design.md,
// executed): saving files an edit task carrying the submitted body in
// full, and the agent judges and integrates it through the CLI pipeline.
// The page file is never touched here (invariant I2/T6) — which also
// dissolves the old optimistic-lock conflict handling: two proposals
// are just two tasks.

func contentHash(b []byte) string {
	h := sha256.Sum256(b)
	return hex.EncodeToString(h[:])
}

func (s *Server) handleEditForm(w http.ResponseWriter, r *http.Request) {
	scan, err := wiki.Scan(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	p, err := scan.Find(r.PathValue("slug"))
	if err != nil {
		http.NotFound(w, r)
		return
	}
	s.render(w, r, http.StatusOK, "edit.html", map[string]any{
		"Title": "edit: " + p.Title,
		"Page":  p,
		"Body":  p.Body,
	})
}

func (s *Server) handleEditSave(w http.ResponseWriter, r *http.Request) {
	scan, err := wiki.Scan(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	p, err := scan.Find(r.PathValue("slug"))
	if err != nil {
		http.NotFound(w, r)
		return
	}
	// Browsers submit textarea content with CRLF line endings.
	body := strings.ReplaceAll(r.FormValue("body"), "\r\n", "\n")
	note := strings.TrimSpace(r.FormValue("note"))
	if strings.TrimSpace(body) == "" && note == "" {
		http.Error(w, "provide a proposed body or an edit request", http.StatusBadRequest)
		return
	}
	if strings.TrimSpace(body) == "" {
		body = ""
	}
	// An unchanged body with no note is a no-op, not a proposal.
	if strings.TrimSpace(body) == strings.TrimSpace(p.Body) && note == "" {
		http.Redirect(w, r, pagePath(p), http.StatusSeeOther)
		return
	}
	raw, err := os.ReadFile(filepath.Join(s.w.Root, p.RelPath))
	if err != nil {
		s.fail(w, err)
		return
	}
	task, err := tasks.FileEdit(s.w, p.Slug, note, body, contentHash(raw), "web", time.Now())
	if err != nil {
		s.fail(w, err)
		return
	}
	http.Redirect(w, r, pagePath(p)+"?tasked="+url.QueryEscape(task.ID), http.StatusSeeOther)
}

package webui

import (
	"log"
	"net/http"
	"sort"
	"strings"
	"time"

	"github.com/neutrospec/canopy/internal/attention"
	"github.com/nicksnyder/go-i18n/v2/i18n"

	"github.com/neutrospec/canopy/internal/reads"
	"github.com/neutrospec/canopy/internal/store"
	"github.com/neutrospec/canopy/internal/wiki"
	"github.com/neutrospec/canopy/internal/wikilock"
)

// Discovery ranks UNREAD pages — "새발견" is meeting a page for the
// first time, complementary to resurface (re-meeting a forgotten one).
// Signals (docs/web-ui-plan-2.md D4): newness, hubness, and affinity
// to recently-read pages. All computed from data we already have.

type discovery struct {
	Page   *wiki.Page
	Score  float64
	Reason string
	Days   int // age since created, for display
}

const affinityRecentK = 10

func (s *Server) discoverRanked(scan *wiki.ScanResult, rs *reads.State, vectors map[string][]float32, now time.Time, loc *i18n.Localizer) []discovery {
	if !rs.HumanAvailable() {
		return nil // Unknown read state is not the same as an unread page.
	}
	var recentVecs [][]float32
	// Affinity blends both doors: recall citations are interest too.
	for _, slug := range rs.RecentAccessSlugs(affinityRecentK) {
		if v, ok := vectors[slug]; ok {
			recentVecs = append(recentVecs, v)
		}
	}
	backlinks := scan.Backlinks()

	var out []discovery
	for _, p := range scan.Pages {
		if rs.IsRead(p.Slug) {
			continue
		}
		days := 9999
		if t, err := time.Parse("2006-01-02", p.Created); err == nil {
			days = int(now.Sub(t).Hours() / 24)
		}
		newness := 0.0
		if days <= 30 {
			newness = 1 - float64(days)/30
		}
		hub := float64(len(backlinks[strings.ToLower(p.Slug)])) / 5
		if hub > 1 {
			hub = 1
		}
		affinity := 0.0
		if v, ok := vectors[strings.ToLower(p.Slug)]; ok {
			for _, rv := range recentVecs {
				if c := store.Cosine(v, rv); c > affinity {
					affinity = c
				}
			}
		}
		score := 0.4*newness + 0.3*hub + 0.3*affinity
		if score <= 0 {
			continue
		}
		reasonID := "reason_new"
		switch {
		case affinity >= newness && 0.3*affinity >= 0.3*hub && affinity > 0:
			reasonID = "reason_affinity"
		case 0.3*hub > 0.4*newness && hub > 0:
			reasonID = "reason_hub"
		case newness == 0:
			reasonID = "reason_unread"
		}
		reason := localizeString(loc, reasonID)
		out = append(out, discovery{Page: p, Score: score, Reason: reason, Days: days})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Score > out[j].Score })
	return out
}

// --- handlers ---

// handleReadMark is the explicit ✓ button (plain form POST — works
// without JS; the auto path is /api/read).
func (s *Server) handleReadMark(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	lease, err := wikilock.AcquireShared(r.Context(), s.w.Root)
	if err != nil {
		s.fail(w, err)
		return
	}
	defer lease.Unlock()
	slug := strings.ToLower(strings.TrimSpace(r.PathValue("slug")))
	action := r.FormValue("action")
	if action != "read" && action != "unread" {
		http.Error(w, "unknown read action", http.StatusBadRequest)
		return
	}
	rs, err := reads.Load(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	scan, err := wiki.Scan(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	p, findErr := scan.Find(r.PathValue("slug"))
	if findErr == nil {
		slug = strings.ToLower(p.Slug)
	}
	if findErr != nil && !(action == "unread" && rs.IsRead(slug)) {
		http.NotFound(w, r)
		return
	}
	kind := attention.KindRead
	if action == "unread" {
		rs.Unmark(slug)
	} else {
		if rs.IsRead(slug) {
			kind = attention.KindReread
		}
		rs.Mark(slug, "explicit", time.Now())
	}
	if err := rs.SaveLocked(s.w); err != nil {
		s.fail(w, err)
		return
	}
	if action == "read" {
		s.logEvent(slug, kind, "")
	}
	if p != nil {
		http.Redirect(w, r, pagePath(p), http.StatusSeeOther)
	} else {
		http.Redirect(w, r, "/browse", http.StatusSeeOther)
	}
}

// handleReadAuto records a dwell+scroll detected read. It never
// downgrades and never re-marks an already-read page.
func (s *Server) handleReadAuto(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	lease, err := wikilock.AcquireShared(r.Context(), s.w.Root)
	if err != nil {
		s.fail(w, err)
		return
	}
	defer lease.Unlock()
	slug := strings.ToLower(strings.TrimSpace(r.PathValue("slug")))
	scan, err := wiki.Scan(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	p, findErr := scan.Find(r.PathValue("slug"))
	if findErr != nil {
		http.NotFound(w, r)
		return
	}
	slug = strings.ToLower(p.Slug)
	rs, err := reads.Load(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	if !rs.IsRead(slug) {
		rs.Mark(slug, "auto", time.Now())
		if err := rs.SaveLocked(s.w); err != nil {
			s.fail(w, err)
			return
		}
		s.logEvent(slug, attention.KindRead, "")
	}
	s.emit(w, map[string]any{"read": true})
}

func (s *Server) handleDiscover(w http.ResponseWriter, r *http.Request) {
	scan, err := wiki.Scan(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	vectors, current, indexErr := s.currentVectors(r.Context(), scan)
	if indexErr != nil {
		log.Printf("discovery index: %v", indexErr)
	}
	rs, readErr := reads.Load(s.w)
	if readErr != nil {
		log.Printf("discovery reads: %v", readErr)
	}
	loc := s.loc(r)
	ranked := s.discoverRanked(scan, rs, vectors, time.Now(), loc)
	readCount := 0
	for _, p := range scan.Pages {
		if rs.IsRead(p.Slug) {
			readCount++
		}
	}
	pct := 0
	if len(scan.Pages) > 0 {
		pct = readCount * 100 / len(scan.Pages)
	}
	s.render(w, r, http.StatusOK, "discover.html", map[string]any{
		"Title":             localizeString(loc, "title_discover"),
		"Ranked":            ranked,
		"ReadCount":         readCount,
		"UnreadCount":       len(scan.Pages) - readCount,
		"ReadAvailable":     rs.HumanAvailable(),
		"ReadsPartial":      readErr != nil,
		"SemanticAvailable": indexErr == nil && current != nil && current.SemanticReady,
		"Total":             len(scan.Pages),
		"Pct":               pct,
	})
}

// Package webui serves the wiki over HTTP for human browsing.
// The editor queues proposals; agents apply them through the CLI pipeline.
package webui

import (
	"bytes"
	"fmt"
	"html"
	"html/template"
	"regexp"
	"strings"

	chromahtml "github.com/alecthomas/chroma/v2/formatters/html"
	"github.com/yuin/goldmark"
	highlighting "github.com/yuin/goldmark-highlighting/v2"
	"github.com/yuin/goldmark/extension"
	"github.com/yuin/goldmark/parser"
	"github.com/yuin/goldmark/renderer"
	"github.com/yuin/goldmark/util"
	"go.abhg.dev/goldmark/mermaid"

	"github.com/neutrospec/canopy/internal/wiki"
)

var md = goldmark.New(
	goldmark.WithExtensions(
		extension.GFM,
		extension.Footnote,
		// Server-side syntax highlighting: chroma with CSS classes so
		// static/chroma.css can restyle tokens for light and dark.
		highlighting.NewHighlighting(
			highlighting.WithFormatOptions(chromahtml.WithClasses(true)),
		),
		// ```mermaid blocks become <pre class="mermaid">; app.js lazy-
		// loads the vendored script only when a page contains one.
		&mermaid.Extender{RenderMode: mermaid.RenderModeClient, NoScript: true},
	),
	goldmark.WithParserOptions(parser.WithAutoHeadingID(), parser.WithInlineParsers(util.Prioritized(wikiLinkParser{}, 100))),
	goldmark.WithRendererOptions(renderer.WithNodeRenderers(util.Prioritized(wikiLinkRenderer{}, 100))),
)

// Wikilink with optional #anchor and |alias. Same target charset as
// wiki.ExtractLinks, but capturing all three parts for display.
var linkRe = regexp.MustCompile(`\[\[([^\]\[|#]+)(#[^\]\[|]*)?(\|[^\]\[]*)?\]\]`)

// RenderPage converts a page body to HTML. exists reports whether a
// normalized slug resolves to a page, so missing targets render as
// red links (Wikipedia pattern).
func RenderPage(body string, exists func(slug string) bool) (template.HTML, error) {
	return RenderPageWithResolver(body, func(target string) (string, string, bool) {
		slug := wiki.NormalizeLink(target)
		return slug, slug, exists != nil && exists(slug)
	})
}

// WikiLinkResolver resolves the original target with the same namespace as
// page lookup. reference can be a governed path to disambiguate dotted slugs.
type WikiLinkResolver func(target string) (slug, reference string, found bool)

func RenderPageWithResolver(body string, resolve WikiLinkResolver) (template.HTML, error) {
	ctx := parser.NewContext()
	ctx.Set(wikiResolveKey, resolve)
	var buf bytes.Buffer
	if err := md.Convert([]byte(body), &buf, parser.WithContext(ctx)); err != nil {
		return "", err
	}
	return template.HTML(buf.String()), nil
}

// replaceWikilinks rewrites [[target#anchor|alias]] to inline anchor
// tags, skipping fenced and inline code regions.
func replaceWikilinks(src string, exists func(string) bool) string {
	return outsideCode(src, func(seg string) string {
		return linkRe.ReplaceAllStringFunc(seg, func(m string) string {
			g := linkRe.FindStringSubmatch(m)
			target, anchor, alias := strings.TrimSpace(g[1]), g[2], strings.TrimPrefix(g[3], "|")
			slug := wiki.NormalizeLink(target)
			display := target
			if anchor != "" {
				display += anchor
			}
			if alias != "" {
				display = alias
			}
			class := "wikilink"
			if !exists(slug) {
				class = "wikilink missing"
			}
			return fmt.Sprintf(`<a class=%q href="/page/%s%s" data-slug=%q>%s</a>`,
				class, html.EscapeString(slug), html.EscapeString(anchor), html.EscapeString(slug), html.EscapeString(display))
		})
	})
}

// outsideCode applies f to the parts of src not inside fenced blocks
// or inline code spans.
func outsideCode(src string, f func(string) string) string {
	return wiki.OutsideCode(src, f)
}

// FirstParagraph returns a plain-text excerpt of a page body for
// previews and search fallbacks.
func FirstParagraph(body string, maxRunes int) string {
	for _, para := range strings.Split(body, "\n\n") {
		t := strings.TrimSpace(para)
		if t == "" || strings.HasPrefix(t, "#") || strings.HasPrefix(t, "```") ||
			strings.HasPrefix(t, ">") || strings.HasPrefix(t, "---") {
			continue
		}
		t = linkRe.ReplaceAllString(t, "$1")
		t = strings.NewReplacer("**", "", "*", "", "`", "").Replace(t)
		r := []rune(strings.Join(strings.Fields(t), " "))
		if len(r) > maxRunes {
			return string(r[:maxRunes]) + "…"
		}
		return string(r)
	}
	return ""
}

package webui

import (
	"fmt"
	"html"
	"net/url"
	"strings"

	"github.com/neutrospec/canopy/internal/wiki"
	"github.com/yuin/goldmark/ast"
	"github.com/yuin/goldmark/parser"
	"github.com/yuin/goldmark/renderer"
	"github.com/yuin/goldmark/text"
	"github.com/yuin/goldmark/util"
)

var wikiResolveKey = parser.NewContextKey()
var wikiLinkKind = ast.NewNodeKind("CanopyWikiLink")

type wikiLinkNode struct {
	ast.BaseInline
	slug, reference, anchor, display string
	exists                           bool
}

func (n *wikiLinkNode) Kind() ast.NodeKind            { return wikiLinkKind }
func (n *wikiLinkNode) Dump(source []byte, level int) { ast.DumpHelper(n, source, level, nil, nil) }

// Parse inside Goldmark's inline grammar. Fences, indented code and code spans
// remain byte-for-byte source, with no raw-HTML escape hatch for wiki content.
type wikiLinkParser struct{}

func (wikiLinkParser) Trigger() []byte { return []byte{'['} }
func (wikiLinkParser) Parse(parent ast.Node, block text.Reader, pc parser.Context) ast.Node {
	line, _ := block.PeekLine()
	loc := linkRe.FindIndex(line)
	if loc == nil || loc[0] != 0 {
		return nil
	}
	g := linkRe.FindStringSubmatch(string(line[:loc[1]]))
	target, anchor, alias := strings.TrimSpace(g[1]), g[2], strings.TrimPrefix(g[3], "|")
	slug := wiki.NormalizeLink(target)
	display := target + anchor
	if alias != "" {
		display = alias
	}
	n := &wikiLinkNode{slug: slug, reference: target, anchor: strings.TrimPrefix(anchor, "#"), display: display}
	if resolve, ok := pc.Get(wikiResolveKey).(WikiLinkResolver); ok && resolve != nil {
		n.slug, n.reference, n.exists = resolve(target)
	}
	block.Advance(loc[1])
	return n
}

type wikiLinkRenderer struct{}

func (wikiLinkRenderer) RegisterFuncs(reg renderer.NodeRendererFuncRegisterer) {
	reg.Register(wikiLinkKind, func(w util.BufWriter, source []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
		if !entering {
			return ast.WalkContinue, nil
		}
		n := node.(*wikiLinkNode)
		class := "wikilink"
		if !n.exists {
			class += " missing"
		}
		href := "/page/" + url.PathEscape(n.reference)
		if n.anchor != "" {
			href += "#" + url.PathEscape(n.anchor)
		}
		_, err := fmt.Fprintf(w, `<a class="%s" href="%s" data-slug="%s">%s</a>`, class, html.EscapeString(href), html.EscapeString(n.slug), html.EscapeString(n.display))
		return ast.WalkSkipChildren, err
	})
}

package webui

import (
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/nicksnyder/go-i18n/v2/i18n"

	"github.com/neutrospec/canopy/internal/tasks"
	"github.com/neutrospec/canopy/internal/wiki"
)

// The web door files delegated tasks; agents perform them; `canopy tasks
// done` verifies the outcome (docs/agent-tasks.md). Filing never edits
// pages (invariant T6), so these handlers only write _meta/tasks/.

// taskView is the page-attached todo-list entry.
type taskView struct {
	ID          string
	TypeLabel   string // localized chip text
	Other       string // connect: the other page's slug (linkified)
	Request     string // edit: the user's request
	Created     string // exact reception timestamp
	Body        string
	Base        string
	StatusLabel string
}

// handleTaskConnect files a connect task for a suggestion the user
// endorsed (the click IS the human judgment; wording/placement stays
// with the agent).
func (s *Server) handleTaskConnect(w http.ResponseWriter, r *http.Request) {
	scan, err := wiki.Scan(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	pa, errA := scan.Find(r.FormValue("a"))
	pb, errB := scan.Find(r.FormValue("b"))
	if errA != nil || errB != nil || pa.Slug == pb.Slug {
		http.Error(w, "bad or ambiguous pair", http.StatusBadRequest)
		return
	}
	a, b := pa.Slug, pb.Slug
	sim, _ := strconv.ParseFloat(r.FormValue("sim"), 64)
	task, _, err := tasks.FileConnect(s.w, a, b, sim, "web", time.Now())
	if err != nil {
		s.fail(w, err)
		return
	}
	http.Redirect(w, r, pagePath(pa)+"?tasked="+url.QueryEscape(task.ID), http.StatusSeeOther)
}

// handleTaskEdit files an edit request against a page, capturing the
// current content hash so `done` can require the page to have moved.
func (s *Server) handleTaskEdit(w http.ResponseWriter, r *http.Request) {
	scan, err := wiki.Scan(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	p, err := scan.Find(r.PathValue("slug"))
	if err != nil {
		http.NotFound(w, r)
		return
	}
	request := strings.TrimSpace(r.FormValue("request"))
	if request == "" {
		http.Error(w, "provide an edit request", http.StatusBadRequest)
		return
	}
	raw, err := os.ReadFile(filepath.Join(s.w.Root, p.RelPath))
	if err != nil {
		s.fail(w, err)
		return
	}
	task, err := tasks.FileEdit(s.w, p.Slug, request, "", contentHash(raw), "web", time.Now())
	if err != nil {
		s.fail(w, err)
		return
	}
	http.Redirect(w, r, pagePath(p)+"?tasked="+url.QueryEscape(task.ID), http.StatusSeeOther)
}

// taskRow is one entry on the /special/tasks screen.
type taskRow struct {
	ID          string
	TypeLabel   string
	StatusLabel string
	Pages       []string
	Request     string
	Body        string // edit proposal text (web editor submissions)
	Base        string
	Note        string
	Door        string
	Created     string // RFC3339
	Closed      string // RFC3339
	// CanCancel: the requester may withdraw a pending edit request from
	// the web. Connect tasks are not cancellable here — a web dismiss
	// would permanently suppress the pair's button (T4), which is the
	// agent's judgment to make.
	CanCancel bool
}

func taskStatusLabel(lc *i18n.Localizer, status string) string {
	switch status {
	case tasks.StatusPending, tasks.StatusDone, tasks.StatusDismissed:
		return localizeString(lc, "tasks_status_"+status)
	default:
		return status
	}
}

func (s *Server) typeLabel(lc *i18n.Localizer, typ string) string {
	switch typ {
	case tasks.TypeConnect:
		return localizeString(lc, "task_type_connect")
	case tasks.TypeEdit:
		return localizeString(lc, "task_type_edit")
	default: // future type from a newer canopy: show it raw, don't hide it
		return typ
	}
}

// handleTasksPage renders the queue: pending first (oldest first, the
// loop's processing order), then recently closed for a sense of motion.
func (s *Server) handleTasksPage(w http.ResponseWriter, r *http.Request) {
	list, err := tasks.Load(s.w)
	if err != nil {
		s.fail(w, err)
		return
	}
	lc := s.loc(r)
	var pending, closed []taskRow
	for _, t := range list {
		row := taskRow{
			ID: t.ID, TypeLabel: s.typeLabel(lc, t.Type), Pages: t.Pages,
			Request: t.Request, Body: t.Body, Base: t.Base, Note: t.Note, Door: t.Door,
			StatusLabel: taskStatusLabel(lc, t.Status),
			Created:     t.Created, Closed: t.Closed,
		}
		if t.Status == tasks.StatusPending {
			row.CanCancel = t.Type == tasks.TypeEdit
			pending = append(pending, row)
			continue
		}
		row.StatusLabel = taskStatusLabel(lc, t.Status)
		closed = append(closed, row)
	}
	// closed: newest first, capped — this is a pulse, not an archive
	sort.SliceStable(closed, func(i, j int) bool { return closed[i].Closed > closed[j].Closed })
	if len(closed) > 30 {
		closed = closed[:30]
	}
	s.render(w, r, http.StatusOK, "tasks.html", map[string]any{
		"Title":   localizeString(lc, "tasks_title"),
		"Pending": pending,
		"Closed":  closed,
	})
}

// handleTaskCancel withdraws a pending edit request from the web (the
// requester changing their mind). Everything else closes through the
// CLI where done is verified.
func (s *Server) handleTaskCancel(w http.ResponseWriter, r *http.Request) {
	t, err := tasks.Get(s.w, r.PathValue("id"))
	if err != nil {
		http.NotFound(w, r)
		return
	}
	if t.Type != tasks.TypeEdit || t.Status != tasks.StatusPending {
		http.Error(w, "only pending edit requests can be withdrawn here", http.StatusBadRequest)
		return
	}
	if _, err := tasks.Close(s.w, nil, t.ID, tasks.StatusDismissed, "웹에서 철회", "web", time.Now()); err != nil {
		s.fail(w, err)
		return
	}
	http.Redirect(w, r, "/special/tasks", http.StatusSeeOther)
}

// pageTasks returns the page's pending todo list plus the set of slugs
// with an already-filed connect task (any status — dismissed pairs must
// not re-offer the button). Best-effort: a broken queue never breaks
// page serving.
func (s *Server) pageTasks(slug string, lc *i18n.Localizer) (views []taskView, filed map[string]bool, err error) {
	filed = map[string]bool{}
	list, err := tasks.Load(s.w)
	if err != nil {
		return nil, filed, err
	}
	slug = strings.ToLower(slug)
	for _, t := range list {
		if !t.Involves(slug) {
			continue
		}
		if t.Type == tasks.TypeConnect {
			for _, p := range t.Pages {
				if strings.ToLower(p) != slug {
					filed[strings.ToLower(p)] = true
				}
			}
		}
		if t.Status != tasks.StatusPending {
			continue
		}
		v := taskView{ID: t.ID, TypeLabel: s.typeLabel(lc, t.Type), Created: t.Created, Body: t.Body, Base: t.Base, StatusLabel: taskStatusLabel(lc, t.Status)}
		switch t.Type {
		case tasks.TypeConnect:
			for _, p := range t.Pages {
				if strings.ToLower(p) != slug {
					v.Other = p
				}
			}
		default:
			v.Request = t.Request
			if v.Request == "" && t.Body != "" {
				v.Request = localizeString(lc, "task_proposal_marker")
			}
		}
		views = append(views, v)
	}
	return views, filed, nil
}

// Progressive enhancements for the server-rendered wiki. No dependencies.
(function () {
  "use strict";
  const messages = JSON.parse(document.getElementById("ui-messages")?.textContent || "{}");
  const t = (id) => messages[id] || id;
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  }[c]));
  const typing = (el) => el?.isContentEditable || /^(input|textarea|select)$/i.test(el?.tagName || "");

  // --- workspace navigation and search shortcuts ----------------------
  const sidebar = document.getElementById("site-nav");
  const toggle = document.getElementById("navtoggle");
  const mobile = matchMedia("(max-width: 800px)");
  if (sidebar && toggle) {
    document.documentElement.classList.add("js-nav");
    function setNav(open) {
      sidebar.hidden = !open;
      toggle.setAttribute("aria-expanded", String(open));
    }
    function adaptNav() {
      toggle.hidden = !mobile.matches;
      setNav(!mobile.matches);
    }
    adaptNav();
    mobile.addEventListener("change", adaptNav);
    toggle.addEventListener("click", () => setNav(sidebar.hidden));
    document.addEventListener("click", (e) => {
      if (mobile.matches && !sidebar.contains(e.target) && !toggle.contains(e.target)) setNav(false);
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && mobile.matches && !sidebar.hidden) {
        setNav(false);
        toggle.focus();
      }
    });
  }
  const searchInput = document.querySelector('.topbar input[name="q"]');
  document.querySelector(".searchfocus")?.addEventListener("click", () => searchInput?.focus());
  document.addEventListener("keydown", (e) => {
    if (e.defaultPrevented || e.isComposing) return;
    if (((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") ||
        (e.key === "/" && !e.metaKey && !e.ctrlKey && !e.altKey && !typing(e.target))) {
      if (searchInput) { e.preventDefault(); searchInput.focus(); }
    }
  });

  const contextWide = matchMedia("(min-width: 1101px)");
  document.querySelectorAll("details[data-desktop-open]").forEach((panel) => {
    const adapt = () => { panel.open = contextWide.matches; };
    adapt();
    contextWide.addEventListener?.("change", adapt);
  });

  // --- instant search --------------------------------------------------
  document.querySelectorAll(".searchbar").forEach((form, index) => {
    const input = form.querySelector("input[name=q]");
    if (!input) return;
    const box = document.createElement("div");
    box.className = "ac";
    box.id = `search-options-${index}`;
    box.setAttribute("role", "listbox");
    box.hidden = true;
    form.appendChild(box);
    input.setAttribute("role", "combobox");
    input.setAttribute("aria-autocomplete", "list");
    input.setAttribute("aria-controls", box.id);
    input.setAttribute("aria-expanded", "false");

    let items = [], sel = -1, timer = null, seq = 0, request = null, composing = false;
    function invalidate() {
      clearTimeout(timer);
      seq++;
      request?.abort();
      request = null;
    }
    function render() {
      box.innerHTML = items.map((it, i) =>
        `<a id="${box.id}-${i}" role="option" aria-selected="${i === sel}" tabindex="-1" ` +
        `href="${esc(it.URL || "/page/" + encodeURIComponent(it.Slug))}" class="${i === sel ? "sel" : ""}">` +
        `<b>${esc(it.Title || it.Slug)}</b><span class="muted">${esc(it.Slug)}</span></a>`
      ).join("");
      box.hidden = items.length === 0;
      input.setAttribute("aria-expanded", String(!box.hidden));
      if (sel >= 0) input.setAttribute("aria-activedescendant", `${box.id}-${sel}`);
      else input.removeAttribute("aria-activedescendant");
      box.querySelector('[aria-selected="true"]')?.scrollIntoView({ block: "nearest" });
    }
    function close() {
      invalidate();
      items = []; sel = -1;
      render();
    }
    function schedule() {
      // Invalidate at the keystroke, before the debounce: an older response
      // must not reopen results while the new request is still waiting.
      close();
      const q = input.value.trim();
      if (!q || composing) return;
      const my = seq;
      timer = setTimeout(async () => {
        request = new AbortController();
        try {
          const r = await fetch(`/api/search?q=${encodeURIComponent(q)}&k=8`, { signal: request.signal });
          if (!r.ok) throw new Error("search failed");
          const d = await r.json();
          if (my !== seq) return;
          items = Array.isArray(d.results) ? d.results.filter((it) => typeof it.Slug === "string") : [];
          sel = -1;
          render();
        } catch {
          if (my === seq) { items = []; sel = -1; render(); }
          // The ordinary search form remains usable when the API is down.
        }
      }, 150);
    }
    input.addEventListener("input", schedule);
    input.addEventListener("compositionstart", () => { composing = true; close(); });
    input.addEventListener("compositionend", () => { composing = false; schedule(); });
    input.addEventListener("keydown", (e) => {
      if (composing || e.isComposing) return;
      if (e.key === "Escape" || e.key === "Tab") { close(); return; }
      if (box.hidden) return;
      if (e.key === "ArrowDown") { sel = Math.min(sel + 1, items.length - 1); render(); e.preventDefault(); }
      else if (e.key === "ArrowUp") { sel = Math.max(sel - 1, -1); render(); e.preventDefault(); }
      else if (e.key === "Enter" && sel >= 0) { location.href = items[sel].URL || "/page/" + encodeURIComponent(items[sel].Slug); e.preventDefault(); }
    });
    document.addEventListener("click", (e) => { if (!form.contains(e.target)) close(); });
  });

  // --- wikilink previews (exposure, never a read) -----------------------
  const cache = new Map();
  let pop = null, ptimer = null;
  function hidePop() {
    clearTimeout(ptimer);
    if (pop) { pop.remove(); pop = null; }
  }
  async function showPop(a) {
    const slug = a.dataset.slug;
    let d = cache.get(slug);
    if (!d) {
      try {
        const response = await fetch(`/api/preview/${encodeURIComponent(slug)}`);
        if (!response.ok) return;
        d = await response.json();
      } catch { return; }
      cache.set(slug, d);
    }
    if (!d.exists || !d.excerpt || !a.matches(":hover")) return;
    hidePop();
    pop = document.createElement("div");
    pop.className = "popover";
    pop.innerHTML = `<b>${esc(d.title)}</b><p>${esc(d.excerpt)}</p>`;
    document.body.appendChild(pop);
    const r = a.getBoundingClientRect();
    pop.style.left = Math.max(8, Math.min(r.left + scrollX, innerWidth + scrollX - pop.offsetWidth - 8)) + "px";
    const y = r.bottom + 6 + pop.offsetHeight > innerHeight ? r.top - pop.offsetHeight - 6 : r.bottom + 6;
    pop.style.top = (Math.max(8, y) + scrollY) + "px";
  }
  document.addEventListener("mouseover", (e) => {
    const a = e.target.closest?.("a.wikilink[data-slug]:not(.missing)");
    if (!a) return;
    clearTimeout(ptimer);
    ptimer = setTimeout(() => showPop(a), 250);
  });
  document.addEventListener("mouseout", (e) => {
    if (e.target.closest?.("a.wikilink[data-slug]")) hidePop();
  });

  // --- code copy, section links and outline, diagrams, math ------------
  const loadScript = (src) => new Promise((ok, bad) => {
    const s = document.createElement("script");
    s.src = src; s.onload = ok; s.onerror = bad;
    document.head.appendChild(s);
  });
  const renderFailure = (where, id) => {
    if (where.querySelector(`.rendererror[data-kind="${id}"]`)) return;
    const status = document.createElement("p");
    status.className = "rendererror";
    status.dataset.kind = id;
    status.setAttribute("role", "status");
    status.textContent = t(id);
    where.appendChild(status);
  };
  const dark = matchMedia("(prefers-color-scheme: dark)").matches;
  const prose = document.querySelector(".prose");
  if (prose) {
    // new pages include a body H1 as well as the frontmatter title. Keep
    // the source intact and collapse only an exact duplicate in the view.
    const title = document.querySelector("article > .pagehead h1");
    const first = prose.firstElementChild;
    if (title && first?.tagName === "H1" && first.textContent.trim() === title.textContent.trim()) first.hidden = true;
    prose.querySelectorAll("pre").forEach((pre) => {
      if (pre.classList.contains("mermaid")) return;
      const btn = document.createElement("button");
      btn.className = "copybtn";
      btn.type = "button";
      btn.textContent = t("copy_button");
      let reset = null;
      btn.addEventListener("click", async () => {
        clearTimeout(reset);
        btn.disabled = true;
        try {
          const code = pre.querySelector("code");
          const text = code ? code.textContent : Array.from(pre.childNodes).filter((n) => n !== btn).map((n) => n.textContent).join("");
          await navigator.clipboard.writeText(text);
          btn.textContent = t("copy_done");
        } catch { btn.textContent = t("copy_failed"); }
        finally { btn.disabled = false; }
        reset = setTimeout(() => { btn.textContent = t("copy_button"); }, 1500);
      });
      pre.appendChild(btn);
    });

    const toc = document.getElementById("page-toc");
    prose.querySelectorAll("h2[id], h3[id], h4[id]").forEach((h) => {
      const title = h.textContent;
      const a = document.createElement("a");
      a.className = "hanchor";
      a.href = "#" + h.id;
      a.textContent = "#";
      a.setAttribute("aria-label", `${t("heading_link")}: ${title}`);
      h.appendChild(a);
      if (toc) {
        const li = document.createElement("li");
        if (h.tagName !== "H2") li.className = "toc-sub";
        const link = document.createElement("a");
        link.href = "#" + h.id;
        link.textContent = title;
        li.appendChild(link);
        toc.appendChild(li);
      }
    });
    if (toc?.children.length) document.getElementById("pageoutline").hidden = false;
    prose.querySelectorAll('a[href^="http"]').forEach((a) => {
      a.target = "_blank"; a.rel = "noopener"; a.classList.add("external");
    });
    const diagrams = prose.querySelectorAll("pre.mermaid, div.mermaid");
    if (diagrams.length) {
      const sources = Array.from(diagrams, (node) => node.textContent);
      loadScript("/static/vendor/mermaid.min.js").then(() => {
        window.mermaid.initialize({ startOnLoad: false, theme: dark ? "dark" : "default", securityLevel: "strict", suppressErrorRendering: true });
        return window.mermaid.run({ nodes: diagrams });
      }).catch(() => {
        diagrams.forEach((node, i) => { node.textContent = sources[i]; node.removeAttribute("data-processed"); });
        renderFailure(prose, "diagram_failed");
      });
    }
    const textOnly = (() => {
      const c = prose.cloneNode(true);
      c.querySelectorAll("pre, code").forEach((n) => n.remove());
      return c.textContent;
    })();
    if (/\$\$[^$]+\$\$|(^|[^\\$])\$[^\s$][^$\n]*\$|\\\(|\\\[/.test(textOnly)) {
      // Explicit package list: no autoload/require and no remote extensions.
      // Color and physics are pinned local components (vendor/assets.json).
      window.MathJax = {
        loader: {
          paths: { mathjax: "/static/vendor" },
          load: ["[tex]/color", "[tex]/physics"],
          source: { "[tex]/color": "/static/vendor/mathjax-color.js", "[tex]/physics": "/static/vendor/mathjax-physics.js" },
        },
        tex: {
          packages: ["base", "ams", "newcommand", "color", "physics"],
          inlineMath: [["$", "$"], ["\\(", "\\)"]], displayMath: [["$$", "$$"], ["\\[", "\\]"]],
          formatError: (jax, error) => {
            renderFailure(prose, "math_failed");
            const source = document.createElement("details");
            source.className = "render-source";
            const summary = document.createElement("summary"); summary.textContent = t("math_source");
            const code = document.createElement("pre"); code.textContent = jax.latex;
            source.appendChild(summary); source.appendChild(code); prose.appendChild(source);
            return jax.formatError(error);
          },
        },
        options: { enableMenu: false },
        svg: { fontCache: "global" },
        startup: { typeset: false },
      };
      loadScript("/static/vendor/tex-svg.js").then(() => window.MathJax.startup.promise)
        .then(() => window.MathJax.typesetPromise([prose]))
        .catch(() => { renderFailure(prose, "math_failed"); });
    }
  }

  // --- read tracking ---------------------------------------------------
  const article = document.querySelector("article[data-slug]");
  if (article) {
    document.addEventListener("keydown", (e) => {
      if (e.defaultPrevented || e.isComposing || e.repeat || e.key !== "r" || e.metaKey || e.ctrlKey || e.altKey || typing(e.target)) return;
      document.querySelector('#readform button[value="read"]')?.click();
    });
    const secs = +article.dataset.readSecs;
    if (secs) {
      const slug = article.dataset.readRef || article.dataset.slug;
      let visibleMs = 0, maxScroll = 0, sent = false;
      const scrolled = () => {
        const h = document.documentElement.scrollHeight;
        return h <= innerHeight + 50 ? 1 : (scrollY + innerHeight) / h;
      };
      const onScroll = () => { maxScroll = Math.max(maxScroll, scrolled()); };
      onScroll();
      addEventListener("scroll", onScroll, { passive: true });
      const tick = setInterval(async () => {
        if (document.visibilityState !== "visible" || sent) return;
        visibleMs += 1000;
        if (visibleMs >= secs * 1000 && maxScroll >= .7) {
          sent = true;
          clearInterval(tick);
          try {
            const response = await fetch(`/api/read/${encodeURIComponent(slug)}?source=auto`, { method: "POST" });
            if (!response.ok || response.redirected) throw new Error(response.status === 401 ? "auth" : "read");
            if (!/^application\/json(?:\s*;|$)/i.test(response.headers.get("content-type") || "")) throw new Error("read");
            const data = await response.json();
            if (data?.read !== true) throw new Error("read");
            const form = document.getElementById("readform");
            if (form) form.innerHTML =
              `<span class="chip readmark">✓ ${esc(t("page_read_label"))} <small>${esc(t("page_auto"))}</small></span>` +
              `<button class="chip" name="action" value="read" title="${esc(t("page_reread_title"))}">${esc(t("page_reread"))}</button>` +
              `<button class="chip" name="action" value="unread" title="${esc(t("page_unread_title"))}">${esc(t("page_cancel"))}</button>`;
          } catch (error) {
            // Preserve the native form and its input values on every failure.
            const status = document.getElementById("read-status");
            if (status) { status.hidden = false; status.textContent = t(error.message === "auth" ? "page_read_auth" : "page_read_failed"); }
          }
        }
      }, 1000);
    }
  }

  const langsel = document.querySelector("details.langsel");
  if (langsel) {
    document.addEventListener("click", (e) => { if (langsel.open && !langsel.contains(e.target)) langsel.open = false; });
    document.addEventListener("keydown", (e) => { if (e.key === "Escape" && langsel.open) langsel.open = false; });
  }
})();

{
  "reads": {},
  "version": 1
}

/* UI chrome is compact; article typography keeps room for reading.
   Graph colors are shared with graph.js through the root variables. */
@font-face { font-family: "Pretendard"; src: url("/static/vendor/fonts/PretendardVariable.woff2") format("woff2-variations"); font-weight: 45 920; font-display: swap; }
@font-face { font-family: "MaruBuri"; src: url("/static/vendor/fonts/MaruBuri-Regular.woff2") format("woff2"); font-weight: 400; font-display: swap; }
@font-face { font-family: "MaruBuri"; src: url("/static/vendor/fonts/MaruBuri-Bold.woff2") format("woff2"); font-weight: 700; font-display: swap; }
:root {
  color-scheme: light;
  --bg: #f5f6f4; --fg: #26332c; --muted: #657269; --line: #dfe5df;
  --chip: #edf1ed; --card: #fff; --accent: #376c4e; --on-accent: #fff;
  --link: #376989; --missing: #b23632; --warm: #b6873c; --warm-ink: #876021;
  --shadow: 0 8px 28px rgba(27, 44, 33, .12);
  --header-height: 3.4rem; --sidebar-width: 11.5rem;
  --serif: "MaruBuri", "Apple Myungjo", serif;
  --sans: "Pretendard", -apple-system, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, monospace;
}
@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
    --bg: #141816; --fg: #e2e8e3; --muted: #a1ada4; --line: #303b33;
    --chip: #242d27; --card: #1b221e; --accent: #85c6a0; --on-accent: #15261c;
    --link: #86bbd7; --missing: #f19185; --warm: #ceaa68; --warm-ink: #d4b477;
    --shadow: 0 8px 28px rgba(0, 0, 0, .3);
  }
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
html { scroll-behavior: smooth; scroll-padding-top: calc(var(--header-height) + 1rem); }
body { margin: 0; background: var(--bg); color: var(--fg); font: 14px/1.6 var(--sans); -webkit-font-smoothing: antialiased; font-variant-numeric: tabular-nums; }
a { color: var(--link); text-decoration: none; overflow-wrap: anywhere; }
a:hover { text-decoration: underline; text-underline-offset: 3px; }
button, input, textarea, select { font: inherit; }
button { cursor: pointer; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 3px; }
:disabled { cursor: wait; opacity: .6; }
h1, h2, h3, h4, p { overflow-wrap: anywhere; }
h1 { font-size: 1.7rem; line-height: 1.35; letter-spacing: -.025em; margin: 0 0 .75rem; font-weight: 680; }
h2 { font-size: 1rem; font-weight: 650; margin: 1.6rem 0 .65rem; }
p { margin: .65rem 0; }
.muted { color: var(--muted); font-size: .9em; }
.icon-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
.icon { flex: 0 0 auto; width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.skiplink { position: fixed; left: 1rem; top: -5rem; z-index: 100; padding: .65rem 1rem; background: var(--accent); color: var(--on-accent); border-radius: 6px; }
.skiplink:focus { top: .5rem; }

/* Persistent search and grouped navigation. */
.topbar { display: flex; align-items: center; gap: 1.3rem; height: var(--header-height); padding: 0 1.25rem 0 1rem; position: fixed; inset: 0 0 auto; z-index: 50; background: var(--card); border-bottom: 1px solid var(--line); }
.brandrow { display: flex; align-items: center; gap: .65rem; flex: 0 0 calc(var(--sidebar-width) - 2.3rem); }
.brand { display: inline-flex; gap: .5rem; align-items: center; color: var(--fg); font-size: 1.28rem; letter-spacing: -.04em; font-weight: 700; text-decoration: none !important; }
.brandmark { width: 28px; height: 28px; fill: none; stroke: var(--accent); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.searchbar { display: flex; align-items: center; gap: .6rem; position: relative; width: 100%; max-width: 34rem; background: var(--bg); border: 1px solid var(--line); border-radius: 7px; padding: 0 .65rem; }
.searchbar > .icon { color: var(--muted); width: 17px; }
.searchbar input { min-width: 0; flex: 1; width: 100%; padding: .45rem 0; border: 0; background: transparent; color: var(--fg); outline: none; }
input::placeholder, textarea::placeholder { color: var(--muted); opacity: .85; }
.searchbar:focus-within { border-color: var(--accent); box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 12%, transparent); }
.searchfocus { background: none; color: var(--muted); border: 0; padding: .2rem; }
kbd { font: .72rem var(--mono); border: 1px solid var(--line); border-radius: 4px; padding: .1rem .3rem; }
.location { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--muted); font-size: .8rem; }
.iconbutton { display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 34px; border: 1px solid var(--line); background: var(--card); color: var(--fg); border-radius: 6px; }
.sidebar { position: fixed; top: var(--header-height); bottom: 0; left: 0; width: var(--sidebar-width); padding: 1rem .75rem; background: var(--card); border-right: 1px solid var(--line); display: flex; flex-direction: column; gap: 1.5rem; overflow-y: auto; z-index: 45; }
.navgroup { display: flex; flex-direction: column; gap: .2rem; }
.navheading { font-size: .68rem; font-weight: 600; color: var(--muted); letter-spacing: .06em; text-transform: uppercase; padding: 0 .7rem; margin: .2rem 0 .5rem; }
.sidebar a { display: flex; gap: .65rem; align-items: center; padding: .5rem .7rem; border-radius: 6px; color: var(--muted); font-size: .86rem; text-decoration: none; }
.sidebar a:hover { background: var(--bg); color: var(--fg); }
.sidebar a[aria-current="page"] { color: var(--accent); background: color-mix(in srgb, var(--accent) 10%, var(--card)); font-weight: 650; }
.navfoot { margin-top: auto; border-top: 1px solid var(--line); padding-top: .6rem; }
.logoutform button { border: 0; background: none; color: var(--muted); padding: .5rem .7rem; font-size: .85rem; }
main { width: calc(100% - var(--sidebar-width)); max-width: 90rem; margin: var(--header-height) 0 0 var(--sidebar-width); padding: 1.25rem 1.6rem 3rem; min-width: 0; }
main:focus { outline: none; }
.pagehead { display: flex; gap: 1.2rem; align-items: center; justify-content: space-between; margin-bottom: .85rem; }
.pagehead h1 { margin-bottom: .35rem; }
.pagehead p { margin: .25rem 0 0; }
.pagehead .eyebrow { margin-bottom: .4rem; color: var(--accent); font-size: .65rem; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; }
.head-date { color: var(--muted); font-size: .78rem; white-space: nowrap; }

/* Overview: counts, useful page lists, and reading context. */
.statsgrid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .8rem; margin-bottom: 1.3rem; }
.stat { display: flex; flex-direction: column; align-items: flex-start; background: var(--card); border: 1px solid var(--line); border-radius: 9px; padding: .8rem 1.1rem; color: var(--fg); text-decoration: none !important; }
.stat:hover { border-color: var(--accent); }
.stat span { color: var(--muted); font-size: .78rem; }
.stat strong { font-size: 1.85rem; font-weight: 630; line-height: 1.45; letter-spacing: -.035em; }
.stat small { color: var(--muted); font-size: .7rem; }
.dashboardgrid { display: grid; grid-template-columns: minmax(0, 1.7fr) minmax(17rem, 1fr); gap: 1.2rem; align-items: start; }
.dashboard-main, .dashboard-side { display: flex; flex-direction: column; gap: 1.1rem; min-width: 0; }
.panel, .card { padding: 1rem 1.15rem; border: 1px solid var(--line); background: var(--card); border-radius: 9px; min-width: 0; }
.card { margin: 1rem 0; }
.card h2 { margin: 0 0 .5rem; }
.sectionhead { display: flex; gap: .6rem; align-items: center; justify-content: space-between; margin-bottom: .65rem; }
.sectionhead h2 { font-size: .88rem; margin: 0; }
.sectionhead > .icon { color: var(--muted); }
.sectionhead > .muted { font-size: .72rem; }
.seeall { color: var(--muted); font-size: .72rem; display: inline-flex; align-items: center; gap: .2rem; white-space: nowrap; font-weight: 400; }
.seeall .icon { width: 14px; height: 14px; }
.seeall:hover { color: var(--accent); }
.band { display: flex; gap: 3px; height: 8px; margin: 1rem 0; }
.bandseg { position: relative; min-width: 6px; overflow: hidden; background: var(--chip); border-radius: 3px; }
.bandseg i { position: absolute; inset: 0; display: block; transform-origin: left; animation: bandfill .6s ease-out both; }
.bandseg.d-entities i { background: var(--link); }
.bandseg.d-concepts i { background: var(--accent); }
.bandseg.d-comparisons i { background: #ac83b9; }
@keyframes bandfill { from { transform: scaleX(0); } to { transform: scaleX(1); } }
.dirlist { list-style: none; padding: 0; margin: 0; font-size: .78rem; }
.dirlist li { display: flex; justify-content: space-between; align-items: center; gap: .5rem; padding: .3rem 0; }
.dirlabel { display: inline-flex; align-items: center; color: var(--muted); gap: .4rem; }
.dirlabel::before { content: ""; width: 6px; height: 6px; flex: 0 0 auto; border-radius: 50%; background: var(--muted); }
.dirlabel.d-entities::before { background: var(--link); }
.dirlabel.d-concepts::before { background: var(--accent); }
.dirlabel.d-comparisons::before { background: #ac83b9; }
