/* Facets, metadata, and action controls. */
.chip { display: inline-flex; gap: .2rem; align-items: center; background: var(--chip); border: 1px solid transparent; border-radius: 5px; padding: .15rem .55rem; min-height: 1.7rem; color: var(--fg); font-size: .75rem; line-height: 1.4; text-decoration: none !important; max-width: 100%; overflow-wrap: anywhere; }
