    toggle.addEventListener("click", () => setNav(sidebar.hidden));
    document.addEventListener("click", (e) => {
      if (mobile.matches && !sidebar.contains(e.target) && !toggle.contains(e.target)) setNav(false);
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && mobile.matches && !sidebar.hidden) {
        setNav(false);
        toggle.focus();
      }
    });
  }
  const searchInput = document.querySelector('.topbar input[name="q"]');
  document.querySelector(".searchfocus")?.addEventListener("click", () => searchInput?.focus());
  document.addEventListener("keydown", (e) => {
    if (e.defaultPrevented || e.isComposing) return;
    if (((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") ||
        (e.key === "/" && !e.metaKey && !e.ctrlKey && !e.altKey && !typing(e.target))) {
      if (searchInput) { e.preventDefault(); searchInput.focus(); }
    }
  });

  const contextWide = matchMedia("(min-width: 1101px)");
  document.querySelectorAll("details[data-desktop-open]").forEach((panel) => {
    const adapt = () => { panel.open = contextWide.matches; };
    adapt();
    contextWide.addEventListener?.("change", adapt);
  });

  // --- instant search --------------------------------------------------
  document.querySelectorAll(".searchbar").forEach((form, index) => {
    const input = form.querySelector("input[name=q]");
    if (!input) return;
    const box = document.createElement("div");
    box.className = "ac";
    box.id = `search-options-${index}`;
    box.setAttribute("role", "listbox");
    box.hidden = true;
    form.appendChild(box);
    input.setAttribute("role", "combobox");
    input.setAttribute("aria-autocomplete", "list");
    input.setAttribute("aria-controls", box.id);
    input.setAttribute("aria-expanded", "false");

    let items = [], sel = -1, timer = null, seq = 0, request = null, composing = false;
    function invalidate() {
      clearTimeout(timer);
      seq++;
      request?.abort();
      request = null;
    }
    function render() {
      box.innerHTML = items.map((it, i) =>
        `<a id="${box.id}-${i}" role="option" aria-selected="${i === sel}" tabindex="-1" ` +
        `href="${esc(it.URL || "/page/" + encodeURIComponent(it.Slug))}" class="${i === sel ? "sel" : ""}">` +
        `<b>${esc(it.Title || it.Slug)}</b><span class="muted">${esc(it.Slug)}</span></a>`
      ).join("");
      box.hidden = items.length === 0;
      input.setAttribute("aria-expanded", String(!box.hidden));
      if (sel >= 0) input.setAttribute("aria-activedescendant", `${box.id}-${sel}`);
      else input.removeAttribute("aria-activedescendant");
      box.querySelector('[aria-selected="true"]')?.scrollIntoView({ block: "nearest" });
    }
    function close() {
      invalidate();
      items = []; sel = -1;
      render();
    }
    function schedule() {
      // Invalidate at the keystroke, before the debounce: an older response
      // must not reopen results while the new request is still waiting.
      close();
      const q = input.value.trim();
      if (!q || composing) return;
      const my = seq;
      timer = setTimeout(async () => {
        request = new AbortController();
        try {
          const r = await fetch(`/api/search?q=${encodeURIComponent(q)}&k=8`, { signal: request.signal });
          if (!r.ok) throw new Error("search failed");
          const d = await r.json();
          if (my !== seq) return;
          items = Array.isArray(d.results) ? d.results.filter((it) => typeof it.Slug === "string") : [];
          sel = -1;
          render();
        } catch {
          if (my === seq) { items = []; sel = -1; render(); }
          // The ordinary search form remains usable when the API is down.
        }
      }, 150);
    }
    input.addEventListener("input", schedule);
    input.addEventListener("compositionstart", () => { composing = true; close(); });
    input.addEventListener("compositionend", () => { composing = false; schedule(); });
    input.addEventListener("keydown", (e) => {
      if (composing || e.isComposing) return;
      if (e.key === "Escape" || e.key === "Tab") { close(); return; }
      if (box.hidden) return;
      if (e.key === "ArrowDown") { sel = Math.min(sel + 1, items.length - 1); render(); e.preventDefault(); }
      else if (e.key === "ArrowUp") { sel = Math.max(sel - 1, -1); render(); e.preventDefault(); }
      else if (e.key === "Enter" && sel >= 0) { location.href = items[sel].URL || "/page/" + encodeURIComponent(items[sel].Slug); e.preventDefault(); }
    });
    document.addEventListener("click", (e) => { if (!form.contains(e.target)) close(); });
  });

  // --- wikilink previews (exposure, never a read) -----------------------
  const cache = new Map();
  let pop = null, ptimer = null;
  function hidePop() {
    clearTimeout(ptimer);
    if (pop) { pop.remove(); pop = null; }
  }
  async function showPop(a) {
    const slug = a.dataset.slug;
    let d = cache.get(slug);
    if (!d) {
      try {
        const response = await fetch(`/api/preview/${encodeURIComponent(slug)}`);
        if (!response.ok) return;
        d = await response.json();
      } catch { return; }
      cache.set(slug, d);
    }
    if (!d.exists || !d.excerpt || !a.matches(":hover")) return;
    hidePop();
    pop = document.createElement("div");
    pop.className = "popover";
    pop.innerHTML = `<b>${esc(d.title)}</b><p>${esc(d.excerpt)}</p>`;
    document.body.appendChild(pop);
    const r = a.getBoundingClientRect();
    pop.style.left = Math.max(8, Math.min(r.left + scrollX, innerWidth + scrollX - pop.offsetWidth - 8)) + "px";
    const y = r.bottom + 6 + pop.offsetHeight > innerHeight ? r.top - pop.offsetHeight - 6 : r.bottom + 6;
    pop.style.top = (Math.max(8, y) + scrollY) + "px";
  }
  document.addEventListener("mouseover", (e) => {
    const a = e.target.closest?.("a.wikilink[data-slug]:not(.missing)");
    if (!a) return;
    clearTimeout(ptimer);
    ptimer = setTimeout(() => showPop(a), 250);
  });
  document.addEventListener("mouseout", (e) => {
    if (e.target.closest?.("a.wikilink[data-slug]")) hidePop();
  });

  // --- code copy, section links and outline, diagrams, math ------------
  const loadScript = (src) => new Promise((ok, bad) => {
    const s = document.createElement("script");
    s.src = src; s.onload = ok; s.onerror = bad;
    document.head.appendChild(s);
  });
  const renderFailure = (where, id) => {
    if (where.querySelector(`.rendererror[data-kind="${id}"]`)) return;
    const status = document.createElement("p");
    status.className = "rendererror";
    status.dataset.kind = id;
    status.setAttribute("role", "status");
    status.textContent = t(id);
    where.appendChild(status);
  };
  const dark = matchMedia("(prefers-color-scheme: dark)").matches;
  const prose = document.querySelector(".prose");
  if (prose) {
    // new pages include a body H1 as well as the frontmatter title. Keep
    // the source intact and collapse only an exact duplicate in the view.
    const title = document.querySelector("article > .pagehead h1");
    const first = prose.firstElementChild;
    if (title && first?.tagName === "H1" && first.textContent.trim() === title.textContent.trim()) first.hidden = true;
    prose.querySelectorAll("pre").forEach((pre) => {
      if (pre.classList.contains("mermaid")) return;
      const btn = document.createElement("button");
      btn.className = "copybtn";
      btn.type = "button";
      btn.textContent = t("copy_button");
      let reset = null;
      btn.addEventListener("click", async () => {
        clearTimeout(reset);
        btn.disabled = true;
        try {
          const code = pre.querySelector("code");
          const text = code ? code.textContent : Array.from(pre.childNodes).filter((n) => n !== btn).map((n) => n.textContent).join("");
          await navigator.clipboard.writeText(text);
          btn.textContent = t("copy_done");
        } catch { btn.textContent = t("copy_failed"); }
        finally { btn.disabled = false; }
        reset = setTimeout(() => { btn.textContent = t("copy_button"); }, 1500);
      });
      pre.appendChild(btn);
    });

    const toc = document.getElementById("page-toc");
    prose.querySelectorAll("h2[id], h3[id], h4[id]").forEach((h) => {
      const title = h.textContent;
      const a = document.createElement("a");
      a.className = "hanchor";
      a.href = "#" + h.id;
      a.textContent = "#";
      a.setAttribute("aria-label", `${t("heading_link")}: ${title}`);
      h.appendChild(a);
      if (toc) {
        const li = document.createElement("li");
        if (h.tagName !== "H2") li.className = "toc-sub";
        const link = document.createElement("a");
        link.href = "#" + h.id;
        link.textContent = title;
        li.appendChild(link);
        toc.appendChild(li);
      }
    });
    if (toc?.children.length) document.getElementById("pageoutline").hidden = false;
    prose.querySelectorAll('a[href^="http"]').forEach((a) => {
      a.target = "_blank"; a.rel = "noopener"; a.classList.add("external");
    });
    const diagrams = prose.querySelectorAll("pre.mermaid, div.mermaid");
    if (diagrams.length) {
      const sources = Array.from(diagrams, (node) => node.textContent);
      loadScript("/static/vendor/mermaid.min.js").then(() => {
        window.mermaid.initialize({ startOnLoad: false, theme: dark ? "dark" : "default", securityLevel: "strict", suppressErrorRendering: true });
        return window.mermaid.run({ nodes: diagrams });
      }).catch(() => {
        diagrams.forEach((node, i) => { node.textContent = sources[i]; node.removeAttribute("data-processed"); });
        renderFailure(prose, "diagram_failed");
      });
    }
    const textOnly = (() => {
      const c = prose.cloneNode(true);
      c.querySelectorAll("pre, code").forEach((n) => n.remove());
      return c.textContent;
    })();
    if (/\$\$[^$]+\$\$|(^|[^\\$])\$[^\s$][^$\n]*\$|\\\(|\\\[/.test(textOnly)) {
      // Explicit package list: no autoload/require and no remote extensions.
      // Color and physics are pinned local components (vendor/assets.json).
      window.MathJax = {
        loader: {
          paths: { mathjax: "/static/vendor" },
          load: ["[tex]/color", "[tex]/physics"],
          source: { "[tex]/color": "/static/vendor/mathjax-color.js", "[tex]/physics": "/static/vendor/mathjax-physics.js" },
        },
        tex: {
          packages: ["base", "ams", "newcommand", "color", "physics"],
          inlineMath: [["$", "$"], ["\\(", "\\)"]], displayMath: [["$$", "$$"], ["\\[", "\\]"]],
          formatError: (jax, error) => {
            renderFailure(prose, "math_failed");
            const source = document.createElement("details");
            source.className = "render-source";
            const summary = document.createElement("summary"); summary.textContent = t("math_source");
            const code = document.createElement("pre"); code.textContent = jax.latex;
            source.appendChild(summary); source.appendChild(code); prose.appendChild(source);
            return jax.formatError(error);
          },
        },
        options: { enableMenu: false },
        svg: { fontCache: "global" },
        startup: { typeset: false },
      };
      loadScript("/static/vendor/tex-svg.js").then(() => window.MathJax.startup.promise)
        .then(() => window.MathJax.typesetPromise([prose]))
        .catch(() => { renderFailure(prose, "math_failed"); });
    }
  }

  // --- read tracking ---------------------------------------------------
  const article = document.querySelector("article[data-slug]");
  if (article) {
    document.addEventListener("keydown", (e) => {
      if (e.defaultPrevented || e.isComposing || e.repeat || e.key !== "r" || e.metaKey || e.ctrlKey || e.altKey || typing(e.target)) return;
      document.querySelector('#readform button[value="read"]')?.click();
    });
    const secs = +article.dataset.readSecs;
    if (secs) {
      const slug = article.dataset.readRef || article.dataset.slug;
      let visibleMs = 0, maxScroll = 0, sent = false;
      const scrolled = () => {
        const h = document.documentElement.scrollHeight;
        return h <= innerHeight + 50 ? 1 : (scrollY + innerHeight) / h;
      };
      const onScroll = () => { maxScroll = Math.max(maxScroll, scrolled()); };
      onScroll();
      addEventListener("scroll", onScroll, { passive: true });
      const tick = setInterval(async () => {
        if (document.visibilityState !== "visible" || sent) return;
        visibleMs += 1000;
        if (visibleMs >= secs * 1000 && maxScroll >= .7) {
          sent = true;
          clearInterval(tick);
          try {
            const response = await fetch(`/api/read/${encodeURIComponent(slug)}?source=auto`, { method: "POST" });
            if (!response.ok || response.redirected) throw new Error(response.status === 401 ? "auth" : "read");
            if (!/^application\/json(?:\s*;|$)/i.test(response.headers.get("content-type") || "")) throw new Error("read");
            const data = await response.json();
            if (data?.read !== true) throw new Error("read");
            const form = document.getElementById("readform");
            if (form) form.innerHTML =
              `<span class="chip readmark">✓ ${esc(t("page_read_label"))} <small>${esc(t("page_auto"))}</small></span>` +
              `<button class="chip" name="action" value="read" title="${esc(t("page_reread_title"))}">${esc(t("page_reread"))}</button>` +
              `<button class="chip" name="action" value="unread" title="${esc(t("page_unread_title"))}">${esc(t("page_cancel"))}</button>`;
          } catch (error) {
            // Preserve the native form and its input values on every failure.
            const status = document.getElementById("read-status");
            if (status) { status.hidden = false; status.textContent = t(error.message === "auth" ? "page_read_auth" : "page_read_failed"); }
          }
        }
      }, 1000);
    }
  }

  const langsel = document.querySelector("details.langsel");
  if (langsel) {
    document.addEventListener("click", (e) => { if (langsel.open && !langsel.contains(e.target)) langsel.open = false; });
    document.addEventListener("keydown", (e) => { if (e.key === "Escape" && langsel.open) langsel.open = false; });
  }
})();

/* UI chrome is compact; article typography keeps room for reading.
   Graph colors are shared with graph.js through the root variables. */
@font-face { font-family: "Pretendard"; src: url("/static/vendor/fonts/PretendardVariable.woff2") format("woff2-variations"); font-weight: 45 920; font-display: swap; }
@font-face { font-family: "MaruBuri"; src: url("/static/vendor/fonts/MaruBuri-Regular.woff2") format("woff2"); font-weight: 400; font-display: swap; }
@font-face { font-family: "MaruBuri"; src: url("/static/vendor/fonts/MaruBuri-Bold.woff2") format("woff2"); font-weight: 700; font-display: swap; }
:root {
  color-scheme: light;
  --bg: #f5f6f4; --fg: #26332c; --muted: #657269; --line: #dfe5df;
  --chip: #edf1ed; --card: #fff; --accent: #376c4e; --on-accent: #fff;
  --link: #376989; --missing: #b23632; --warm: #b6873c; --warm-ink: #876021;
  --shadow: 0 8px 28px rgba(27, 44, 33, .12);
  --header-height: 3.4rem; --sidebar-width: 11.5rem;
  --serif: "MaruBuri", "Apple Myungjo", serif;
  --sans: "Pretendard", -apple-system, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, monospace;
}
@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
    --bg: #141816; --fg: #e2e8e3; --muted: #a1ada4; --line: #303b33;
    --chip: #242d27; --card: #1b221e; --accent: #85c6a0; --on-accent: #15261c;
    --link: #86bbd7; --missing: #f19185; --warm: #ceaa68; --warm-ink: #d4b477;
    --shadow: 0 8px 28px rgba(0, 0, 0, .3);
  }
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
html { scroll-behavior: smooth; scroll-padding-top: calc(var(--header-height) + 1rem); }
body { margin: 0; background: var(--bg); color: var(--fg); font: 14px/1.6 var(--sans); -webkit-font-smoothing: antialiased; font-variant-numeric: tabular-nums; }
a { color: var(--link); text-decoration: none; overflow-wrap: anywhere; }
a:hover { text-decoration: underline; text-underline-offset: 3px; }
button, input, textarea, select { font: inherit; }
button { cursor: pointer; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 3px; }
:disabled { cursor: wait; opacity: .6; }
h1, h2, h3, h4, p { overflow-wrap: anywhere; }
h1 { font-size: 1.7rem; line-height: 1.35; letter-spacing: -.025em; margin: 0 0 .75rem; font-weight: 680; }
h2 { font-size: 1rem; font-weight: 650; margin: 1.6rem 0 .65rem; }
p { margin: .65rem 0; }
.muted { color: var(--muted); font-size: .9em; }
.icon-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
.icon { flex: 0 0 auto; width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.skiplink { position: fixed; left: 1rem; top: -5rem; z-index: 100; padding: .65rem 1rem; background: var(--accent); color: var(--on-accent); border-radius: 6px; }
.skiplink:focus { top: .5rem; }

/* Persistent search and grouped navigation. */
.topbar { display: flex; align-items: center; gap: 1.3rem; height: var(--header-height); padding: 0 1.25rem 0 1rem; position: fixed; inset: 0 0 auto; z-index: 50; background: var(--card); border-bottom: 1px solid var(--line); }
.brandrow { display: flex; align-items: center; gap: .65rem; flex: 0 0 calc(var(--sidebar-width) - 2.3rem); }
.brand { display: inline-flex; gap: .5rem; align-items: center; color: var(--fg); font-size: 1.28rem; letter-spacing: -.04em; font-weight: 700; text-decoration: none !important; }
.brandmark { width: 28px; height: 28px; fill: none; stroke: var(--accent); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.searchbar { display: flex; align-items: center; gap: .6rem; position: relative; width: 100%; max-width: 34rem; background: var(--bg); border: 1px solid var(--line); border-radius: 7px; padding: 0 .65rem; }
.searchbar > .icon { color: var(--muted); width: 17px; }
.searchbar input { min-width: 0; flex: 1; width: 100%; padding: .45rem 0; border: 0; background: transparent; color: var(--fg); outline: none; }
input::placeholder, textarea::placeholder { color: var(--muted); opacity: .85; }
.searchbar:focus-within { border-color: var(--accent); box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 12%, transparent); }
.searchfocus { background: none; color: var(--muted); border: 0; padding: .2rem; }
kbd { font: .72rem var(--mono); border: 1px solid var(--line); border-radius: 4px; padding: .1rem .3rem; }
.location { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--muted); font-size: .8rem; }
.iconbutton { display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 34px; border: 1px solid var(--line); background: var(--card); color: var(--fg); border-radius: 6px; }
.sidebar { position: fixed; top: var(--header-height); bottom: 0; left: 0; width: var(--sidebar-width); padding: 1rem .75rem; background: var(--card); border-right: 1px solid var(--line); display: flex; flex-direction: column; gap: 1.5rem; overflow-y: auto; z-index: 45; }
.navgroup { display: flex; flex-direction: column; gap: .2rem; }
.navheading { font-size: .68rem; font-weight: 600; color: var(--muted); letter-spacing: .06em; text-transform: uppercase; padding: 0 .7rem; margin: .2rem 0 .5rem; }
.sidebar a { display: flex; gap: .65rem; align-items: center; padding: .5rem .7rem; border-radius: 6px; color: var(--muted); font-size: .86rem; text-decoration: none; }
.sidebar a:hover { background: var(--bg); color: var(--fg); }
.sidebar a[aria-current="page"] { color: var(--accent); background: color-mix(in srgb, var(--accent) 10%, var(--card)); font-weight: 650; }
.navfoot { margin-top: auto; border-top: 1px solid var(--line); padding-top: .6rem; }
.logoutform button { border: 0; background: none; color: var(--muted); padding: .5rem .7rem; font-size: .85rem; }
main { width: calc(100% - var(--sidebar-width)); max-width: 90rem; margin: var(--header-height) 0 0 var(--sidebar-width); padding: 1.25rem 1.6rem 3rem; min-width: 0; }
main:focus { outline: none; }
.pagehead { display: flex; gap: 1.2rem; align-items: center; justify-content: space-between; margin-bottom: .85rem; }
.pagehead h1 { margin-bottom: .35rem; }
.pagehead p { margin: .25rem 0 0; }
.pagehead .eyebrow { margin-bottom: .4rem; color: var(--accent); font-size: .65rem; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; }
.head-date { color: var(--muted); font-size: .78rem; white-space: nowrap; }

/* Overview: counts, useful page lists, and reading context. */
.statsgrid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .8rem; margin-bottom: 1.3rem; }
.stat { display: flex; flex-direction: column; align-items: flex-start; background: var(--card); border: 1px solid var(--line); border-radius: 9px; padding: .8rem 1.1rem; color: var(--fg); text-decoration: none !important; }
.stat:hover { border-color: var(--accent); }
.stat span { color: var(--muted); font-size: .78rem; }
.stat strong { font-size: 1.85rem; font-weight: 630; line-height: 1.45; letter-spacing: -.035em; }
.stat small { color: var(--muted); font-size: .7rem; }
.dashboardgrid { display: grid; grid-template-columns: minmax(0, 1.7fr) minmax(17rem, 1fr); gap: 1.2rem; align-items: start; }
.dashboard-main, .dashboard-side { display: flex; flex-direction: column; gap: 1.1rem; min-width: 0; }
.panel, .card { padding: 1rem 1.15rem; border: 1px solid var(--line); background: var(--card); border-radius: 9px; min-width: 0; }
.card { margin: 1rem 0; }
.card h2 { margin: 0 0 .5rem; }
.sectionhead { display: flex; gap: .6rem; align-items: center; justify-content: space-between; margin-bottom: .65rem; }
.sectionhead h2 { font-size: .88rem; margin: 0; }
.sectionhead > .icon { color: var(--muted); }
.sectionhead > .muted { font-size: .72rem; }
.seeall { color: var(--muted); font-size: .72rem; display: inline-flex; align-items: center; gap: .2rem; white-space: nowrap; font-weight: 400; }
.seeall .icon { width: 14px; height: 14px; }
.seeall:hover { color: var(--accent); }
.band { display: flex; gap: 3px; height: 8px; margin: 1rem 0; }
.bandseg { position: relative; min-width: 6px; overflow: hidden; background: var(--chip); border-radius: 3px; }
.bandseg i { position: absolute; inset: 0; display: block; transform-origin: left; animation: bandfill .6s ease-out both; }
.bandseg.d-entities i { background: var(--link); }
.bandseg.d-concepts i { background: var(--accent); }
.bandseg.d-comparisons i { background: #ac83b9; }
@keyframes bandfill { from { transform: scaleX(0); } to { transform: scaleX(1); } }
.dirlist { list-style: none; padding: 0; margin: 0; font-size: .78rem; }
.dirlist li { display: flex; justify-content: space-between; align-items: center; gap: .5rem; padding: .3rem 0; }
.dirlabel { display: inline-flex; align-items: center; color: var(--muted); gap: .4rem; }
.dirlabel::before { content: ""; width: 6px; height: 6px; flex: 0 0 auto; border-radius: 50%; background: var(--muted); }
.dirlabel.d-entities::before { background: var(--link); }
.dirlabel.d-concepts::before { background: var(--accent); }
.dirlabel.d-comparisons::before { background: #ac83b9; }
.today { margin: .7rem 0 0; padding-top: .7rem; border-top: 1px solid var(--line); color: var(--warm-ink); font-size: .75rem; }
.warm { border-top: 2px solid var(--warm); }
.pick-title { font-size: 1.04rem; font-weight: 650; margin-top: .8rem; }
.excerpt { font-size: .83rem; color: var(--muted); line-height: 1.7; }
.fbrow { display: flex; flex-wrap: wrap; gap: .3rem; margin-top: 1rem; }
.fbrow button { font-size: .69rem; }
.bridgepair { display: flex; flex-direction: column; align-items: flex-start; gap: .25rem; font-weight: 550; }
.empty { color: var(--muted); font-size: .85rem; padding: .6rem 0; }
.empty-state { padding: 2rem; text-align: center; }
.empty-state h2 { margin-top: 0; }

/* Facets, metadata, and action controls. */
.chip { display: inline-flex; gap: .2rem; align-items: center; background: var(--chip); border: 1px solid transparent; border-radius: 5px; padding: .15rem .55rem; min-height: 1.7rem; color: var(--fg); font-size: .75rem; line-height: 1.4; text-decoration: none !important; max-width: 100%; overflow-wrap: anywhere; }
.chip.tag::before { content: "#"; color: var(--muted); }
.chip small { color: var(--muted); }
a.chip:hover, button.chip:hover { border-color: var(--accent); }
.chip.active { background: color-mix(in srgb, var(--accent) 9%, var(--card)); border-color: var(--accent); color: var(--accent); }
.chip.reason { background: none; border-color: var(--line); color: var(--muted); font-size: .68rem; }
.chip.readmark, .action-primary { background: var(--accent); color: var(--on-accent); }
.chip.readmark small { color: inherit; opacity: .85; }
.chip.suggest { border: 1px dashed var(--muted); background: transparent; color: var(--link); }
.facets { display: flex; flex-direction: column; gap: .6rem; margin-bottom: 1rem; }
.facetrow { display: flex; flex-wrap: wrap; gap: .35rem; align-items: center; }
.facetlabel { min-width: 3.8rem; color: var(--muted); font-size: .76rem; }
.metacard { display: flex; flex-wrap: wrap; align-items: center; gap: .4rem; margin: .5rem 0 1rem; }
.metacard .muted { font-size: .73rem; }
.pageactions { display: flex; flex-wrap: wrap; align-items: center; gap: .6rem; margin: 0 0 1rem; padding: .6rem 0; border-bottom: 1px solid var(--line); }
.pageactions .chip { min-height: 2rem; padding: .25rem .7rem; }
.readform { display: inline-flex; flex-wrap: wrap; gap: .3rem; align-items: center; }
.readform button, .inlineform button, .taskform button { border-color: var(--line); }
.notice { padding: .75rem 1rem; background: var(--chip); border-left: 3px solid var(--accent); border-radius: 0 6px 6px 0; }
.notice.conflict { border-left-color: var(--missing); }

/* Dense lists keep dates aligned and long titles readable. */
.pagelist, .tasklist { list-style: none; padding: 0; margin: 0; }
.pagelist li { display: flex; align-items: center; flex-wrap: wrap; gap: .5rem .8rem; padding: .65rem 0; border-bottom: 1px solid var(--line); }
.pagelist li:last-child { border-bottom: 0; padding-bottom: .15rem; }
.row-main { flex: 1; min-width: 0; }
.row-main > a { color: var(--fg); font-size: .87rem; font-weight: 560; display: inline-block; overflow-wrap: anywhere; }
.row-main > a:hover { color: var(--link); }
.row-meta { display: flex; flex-wrap: wrap; gap: .4rem .7rem; color: var(--muted); font-size: .69rem; margin-top: .15rem; }
.row-meta a { color: var(--muted); }
.row-date { color: var(--muted); font-size: .72rem; white-space: nowrap; }
a.wikilink.missing { color: var(--missing); }
.results { list-style: none; margin: 0; }
.results li { padding: .85rem 0; border-bottom: 1px solid var(--line); }
.results li:first-child { padding-top: .2rem; }
.results li:last-child { border-bottom: 0; }
.results .wikilink { font-size: 1rem; font-weight: 600; }
.results .snippet { margin: .35rem 0; color: var(--muted); font-size: .84rem; }
.result-slug { color: var(--accent); font: .7rem var(--mono); overflow-wrap: anywhere; }
.progress { height: 6px; background: var(--chip); border-radius: 4px; overflow: hidden; margin: .7rem 0 1.4rem; }
.progressbar { height: 100%; background: var(--accent); }
.tablewrap { overflow-x: auto; margin-top: 1rem; }
.logtable { border-collapse: collapse; width: 100%; font-size: .8rem; }
.logtable th { color: var(--muted); font-weight: 500; text-align: left; white-space: nowrap; }
.logtable th, .logtable td { padding: .65rem .55rem; border-bottom: 1px solid var(--line); vertical-align: top; }
.logtable td { overflow-wrap: anywhere; min-width: 5rem; }
.logtable tbody tr:last-child td { border-bottom: 0; }

/* Article content and an optional section outline. */
.main-page { max-width: 81rem; }
.main-page .pagehead h1 { font-family: var(--serif); font-weight: 700; font-size: 1.9rem; }
.readinglayout { display: grid; grid-template-columns: minmax(0, 1fr) 17rem; gap: 1.6rem; align-items: start; }
.readingbody { min-width: 0; grid-column: 1; grid-row: 1; max-width: 56rem; }
.pagecontext { min-width: 0; grid-column: 2; grid-row: 1; position: sticky; top: calc(var(--header-height) + 5rem); max-height: calc(100dvh - var(--header-height) - 6rem); overflow-y: auto; overscroll-behavior: contain; padding: 0 .2rem .5rem 1rem; border-left: 1px solid var(--line); }

.prose { font-size: 1rem; line-height: 1.85; overflow-wrap: anywhere; }
.prose h1, .prose h2, .prose h3, .prose h4 { line-height: 1.45; margin-top: 1.7em; font-weight: 650; scroll-margin-top: calc(var(--header-height) + 1.2rem); }
.prose h1 { font-size: 1.55rem; }
.prose h2 { font-size: 1.3rem; padding-bottom: .4rem; border-bottom: 1px solid var(--line); }
.prose h3 { font-size: 1.1rem; }
.prose pre { position: relative; max-width: 100%; overflow-x: auto; background: var(--chip); border: 1px solid var(--line); padding: 2.25rem 1rem .85rem; border-radius: 7px; font-size: .8rem; line-height: 1.7; }
.prose pre.mermaid { padding: .8rem 0; background: transparent; border: 0; text-align: center; }
.prose code { padding: .1em .3em; border-radius: 4px; background: var(--chip); font: .86em var(--mono); }
.prose pre code { padding: 0; background: none; font: inherit; font-family: var(--mono); }
.prose blockquote { margin: 1rem 0; padding: .1rem 1rem; border-left: 3px solid var(--accent); background: var(--chip); border-radius: 0 6px 6px 0; }
.prose table { display: block; border-collapse: collapse; max-width: 100%; overflow-x: auto; font-size: .86rem; }
.prose th, .prose td { padding: .45rem .7rem; border: 1px solid var(--line); min-width: 6rem; }
.prose th { background: var(--chip); text-align: left; }
.prose img { max-width: 100%; height: auto; border-radius: 6px; }
.prose hr { border: 0; border-top: 1px solid var(--line); margin: 2rem 0; }
.prose a.external::after { content: "↗"; font-size: .7em; margin-left: .15rem; color: var(--muted); }
.prose mjx-container[jax="SVG"] { max-width: 100%; overflow-x: auto; overflow-y: hidden; }
.prose mjx-container[jax="SVG"][display="true"] { margin: 1rem 0; }
.copybtn { position: absolute; top: .4rem; right: .5rem; padding: .15rem .5rem; background: var(--card); color: var(--muted); border: 1px solid var(--line); border-radius: 4px; font-size: .69rem; opacity: 0; }
.prose pre:hover .copybtn, .prose pre:focus-within .copybtn { opacity: 1; }
.hanchor { margin-left: .4rem; color: var(--muted); opacity: 0; font-weight: 400; }
.prose :is(h2, h3, h4):hover .hanchor, .hanchor:focus { opacity: 1; }
.contextpanel { margin: 0 0 .8rem; padding: 0 0 .65rem; border: 0; border-bottom: 1px solid var(--line); }
.contextpanel > summary { font-size: .8rem; font-weight: 600; color: var(--fg); min-height: 2rem; padding: .25rem 0; }
.contextpanel > summary small { display: block; font-weight: 400; margin: .15rem 0 0 1rem; }
.contextpanel .tasklist { font-size: .78rem; }
.contextpanel .tasklist li { padding: .5rem 0; }
.contextpanel .proposal pre { white-space: pre-wrap; max-height: 12rem; }
.contextpanel .taskform > summary { font-size: .76rem; }
.contextnotice { margin: .5rem 0; font-size: .75rem; }
.taskmeta { margin: .25rem 0; font-size: .75rem; }
.taskheading { display: flex; gap: .35rem .6rem; flex-wrap: wrap; align-items: center; }
.taskheading form { margin-left: auto; }
.taskrequest { white-space: pre-wrap; margin: .4rem 0; }
.taskreceipt { font-size: .75rem; margin-top: .4rem; }
.taskreceipt p { margin: .3rem 0; }
.hash { overflow-wrap: anywhere; word-break: break-all; }
.readstatus, .rendererror { color: var(--missing); font-size: .8rem; }
.rendererror { padding: .65rem .8rem; border-left: 3px solid var(--missing); background: var(--chip); }
.render-source pre { white-space: pre-wrap; }
.pageoutline ol { list-style: none; padding: 0; margin: 0; }
.pageoutline li { margin: .15rem 0; }
.pageoutline .toc-sub { padding-left: .7rem; }
.pageoutline a { display: block; font-size: .75rem; line-height: 1.5; padding: .3rem 0; color: var(--muted); overflow-wrap: anywhere; }
.pageoutline a:hover { color: var(--accent); }
.attn, .graph { margin-top: 1.75rem; padding-top: .8rem; border-top: 1px solid var(--line); }
.backlinks h2, .suggested h2, .tasks h2 { margin: 0 0 .6rem; font-size: .86rem; }
.backlinks ul { padding-left: 1.2rem; }
.suggestrow { display: flex; flex-wrap: wrap; gap: .6rem; }
.suggestitem { display: inline-flex; flex-wrap: wrap; gap: .3rem; align-items: center; }
.inlineform { display: inline; }
.tasklist li { padding: .85rem 0; border-bottom: 1px solid var(--line); overflow-wrap: anywhere; line-height: 1.9; }
.tasklist li:last-child { border-bottom: 0; }
.tasklist .chip { vertical-align: middle; margin-right: .2rem; }
.taskform textarea, .proposenote { width: 100%; padding: .6rem .75rem; margin-top: .5rem; background: var(--card); color: var(--fg); border: 1px solid var(--line); border-radius: 6px; }
.proposal { margin-top: .5rem; }
.proposal pre { max-height: 18rem; overflow: auto; background: var(--chip); border: 1px solid var(--line); border-radius: 6px; padding: .75rem; font: .78rem/1.6 var(--mono); }
summary { cursor: pointer; }
summary:hover { color: var(--fg); }

/* Search suggestions and contextual previews. */
.ac { position: absolute; top: calc(100% + 5px); left: 0; right: 0; z-index: 60; background: var(--card); border: 1px solid var(--line); border-radius: 7px; padding: .25rem; box-shadow: var(--shadow); max-height: min(26rem, 65vh); overflow-y: auto; }
.ac a { display: flex; flex-direction: column; gap: .05rem; padding: .55rem .65rem; color: var(--fg); text-decoration: none; border-radius: 4px; }
.ac a b { font-weight: 560; font-size: .86rem; }
.ac a.sel, .ac a:hover { background: var(--chip); }
.ac a .muted { font-size: .7rem; }
.popover { position: absolute; z-index: 60; max-width: min(23rem, calc(100vw - 16px)); padding: .75rem .9rem; background: var(--card); border: 1px solid var(--line); border-radius: 7px; box-shadow: var(--shadow); font-size: .8rem; pointer-events: none; }
.popover p { margin: .3rem 0 0; color: var(--muted); }

/* Editing and authentication. */
.editform { max-width: 65rem; display: flex; flex-direction: column; gap: .5rem; }
.editform label { color: var(--muted); font-size: .8rem; margin-top: .5rem; }
.editform textarea { width: 100%; min-height: 55vh; padding: 1rem; font: .85rem/1.75 var(--mono); background: var(--card); color: var(--fg); border: 1px solid var(--line); border-radius: 7px; resize: vertical; }
.editform textarea:focus { outline: 2px solid var(--accent); }
.editactions { display: flex; flex-wrap: wrap; align-items: center; gap: 1rem; margin-top: .8rem; }
.editactions button, .authform button { background: var(--accent); color: var(--on-accent); padding: .55rem 1rem; border: 0; border-radius: 6px; font-weight: 550; }
.hero { max-width: 28rem; margin: 4rem auto; text-align: center; }
.hero h1 { font-family: var(--serif); }
.authform { display: flex; flex-direction: column; gap: .8rem; max-width: 22rem; margin: 1.5rem auto; }
.authform input { padding: .6rem .8rem; background: var(--card); color: var(--fg); border: 1px solid var(--line); border-radius: 6px; }
.authform input:focus { outline: 2px solid var(--accent); }

/* Attention timeline and graphs. */
.histday { margin-top: 1.6rem; }
.histday h2 { color: var(--muted); font-size: .8rem; border-bottom: 1px solid var(--line); padding-bottom: .5rem; }
.hist { list-style: none; padding: 0; }
.hist li { display: flex; flex-wrap: wrap; align-items: baseline; gap: .4rem .6rem; margin: .65rem 0; }
.histtime { min-width: 3.2rem; font-size: .75rem; }
.chip.histkind { font-size: .68rem; background: transparent; border-color: var(--line); color: var(--muted); }
.histquery { color: var(--warm-ink); }
.attnsum { margin: .7rem 0; }
.sparkwrap { margin-left: .5rem; vertical-align: middle; }
.spark rect { fill: var(--line); }
.spark rect.on { fill: var(--warm); opacity: .8; }
.graph svg { width: 100%; display: block; margin: .75rem auto; }
.graph line { stroke: var(--line); }
.graph circle { fill: var(--link); }
.graph circle.center { fill: var(--accent); }
.graph circle.missing { fill: var(--missing); }
.graph text { fill: var(--muted); font-size: 11px; }
.graph a:hover text { fill: var(--fg); }
#graph { min-height: 20rem; }
.graphworkspace { display: grid; grid-template-columns: minmax(0, 1fr) 20rem; gap: 1rem; align-items: start; }
.graphwrap { position: relative; min-width: 0; height: calc(100dvh - var(--header-height) - 8rem); min-height: 24rem; overflow: hidden; border: 1px solid var(--line); border-radius: 8px; }
.graphlist { max-height: calc(100dvh - var(--header-height) - 8rem); overflow: auto; font-size: .8rem; }
.graphlist > summary { font-weight: 600; }
.graphneighbors { padding-left: 1rem; list-style: disc; margin: .3rem 0; }
.graphneighbors li { display: list-item; padding: .1rem 0; border: 0; }
.graphstatus { position: absolute; bottom: 2.5rem; left: .8rem; right: .8rem; z-index: 11; padding: .5rem .7rem; background: var(--card); border-radius: 5px; font-size: .8rem; color: var(--missing); }
#graph { width: 100%; height: 100%; }
.graphtools { position: absolute; top: 1rem; left: 1rem; right: 1rem; z-index: 10; display: flex; flex-wrap: wrap; align-items: center; gap: .75rem; width: fit-content; max-width: calc(100% - 2rem); padding: .55rem .8rem; background: var(--card); border: 1px solid var(--line); border-radius: 7px; box-shadow: var(--shadow); }
.graphtools input { min-width: 0; width: 12rem; border: 1px solid var(--line); border-radius: 5px; padding: .35rem .6rem; background: var(--bg); color: var(--fg); font-size: .8rem; }
.legend { display: flex; flex-wrap: wrap; align-items: center; gap: .4rem; font-size: .65rem; color: var(--muted); }
.legend .dot { width: 7px; height: 7px; border-radius: 50%; display: inline-block; }
.dot.d-entities { background: var(--link); }
.dot.d-concepts { background: var(--accent); }
.dot.d-comparisons { background: #ac83b9; }
.dot.d-unread { border: 1px solid var(--missing); }
.dot.d-island { border: 1px dashed var(--warm); }
.graphtip { position: absolute; z-index: 20; max-width: min(21rem, calc(100% - 16px)); pointer-events: none; padding: .65rem .8rem; background: var(--card); border: 1px solid var(--line); border-radius: 7px; font-size: .8rem; line-height: 1.55; box-shadow: var(--shadow); }
.graphtip b { display: block; }
.graphtip .tipmeta { color: var(--muted); font-size: .7rem; }
.graphtip p { margin: .35rem 0 0; color: var(--muted); }
.graphhelp { position: absolute; bottom: .75rem; right: 1rem; left: 1rem; color: var(--muted); font-size: .7rem; text-align: right; pointer-events: none; }

/* Language selection uses native disclosure and ordinary links. */
.langsel { position: relative; flex: 0 0 auto; }
.langsel > summary { display: inline-flex; align-items: center; gap: .45rem; list-style: none; color: var(--muted); font-size: .78rem; user-select: none; }
.langsel > summary::-webkit-details-marker { display: none; }
.langsel > summary::marker { content: ""; }
.langsel .icon { width: 16px; height: 16px; }
.langsel[open] > summary, .langsel > summary:hover { color: var(--fg); }
.langmenu { position: absolute; top: calc(100% + 1rem); right: 0; min-width: 9rem; display: flex; flex-direction: column; padding: .3rem; background: var(--card); border: 1px solid var(--line); border-radius: 7px; box-shadow: var(--shadow); }
.langmenu a, .langmenu .on { display: flex; justify-content: space-between; align-items: center; padding: .5rem .65rem; color: var(--fg); font-size: .85rem; border-radius: 4px; text-decoration: none; }
.langmenu a:hover { background: var(--chip); }
.langmenu .on { color: var(--accent); font-weight: 600; }
.langmenu .on::after { content: "✓"; }

@media (max-width: 1200px) {
  .location { display: none; }
  .topbar .searchbar { flex: 1; }
  .langsel { margin-left: auto; }
  main { padding: 1.4rem; }
  .graphworkspace { grid-template-columns: minmax(0, 1fr); }
  .graphlist { max-height: none; }
}
@media (min-width: 1101px) {
  .pageactions { position: sticky; top: var(--header-height); z-index: 20; background: var(--bg); }
}
@media (max-width: 1100px) {
  .readinglayout { grid-template-columns: minmax(0, 1fr); gap: 1rem; }
  .pagecontext { grid-column: 1; grid-row: 1; position: static; max-height: none; overflow: visible; padding: .5rem .75rem 0; border: 1px solid var(--line); border-radius: 7px; background: var(--card); }
  .readingbody { grid-row: 2; max-width: 100%; }
  .contextpanel { margin-bottom: .4rem; padding-bottom: .4rem; }
  .contextpanel:last-of-type { border-bottom: 0; }
}
@media (max-width: 1000px) {
  .dashboardgrid { grid-template-columns: minmax(0, 1fr) minmax(15rem, 1fr); gap: .9rem; }
  .head-date { display: none; }
  .panel { padding: .85rem 1rem; }
}
@media (max-width: 800px) {
  :root { --sidebar-width: 0rem; --header-height: 3.5rem; }
  .topbar { padding: 0 .7rem; gap: .65rem; }
  .brandrow { flex: 0 0 auto; gap: .4rem; }
  .brand { font-size: 1.1rem; }
  .brandmark { width: 23px; height: 23px; }
  .topbar .searchbar { width: auto; max-width: none; }
  .searchbar input { font-size: .85rem; }
  .sidebar { position: static; width: 100%; flex-direction: row; flex-wrap: wrap; margin-top: var(--header-height); padding: .75rem; border-right: 0; border-bottom: 1px solid var(--line); }
  .navgroup { flex: 1; min-width: 9rem; }
  .navfoot { margin: 0; padding: 0; border: 0; }
  .js-nav .sidebar { position: fixed; top: var(--header-height); bottom: auto; margin: 0; max-height: calc(100dvh - var(--header-height)); overflow-y: auto; box-shadow: var(--shadow); }
  main { width: 100%; margin-left: 0; }
  html:not(.js-nav) main { margin-top: 0; }
  .sidebar a { min-height: 2.75rem; }
  .langsel summary { min-height: 2.75rem; }
  .iconbutton { width: 38px; height: 38px; }
  .statsgrid { gap: .6rem; }
  .stat { padding: .75rem .85rem; }
  .stat strong { font-size: 1.6rem; }
  .copybtn { opacity: 1; }
  .graphwrap { min-height: 22rem; height: 58dvh; }
}
@media (max-width: 600px) {
  main { padding: 1.15rem .85rem 3rem; }
  h1 { font-size: 1.45rem; }
  .pagehead { align-items: flex-start; gap: .5rem; }
  .pagehead .chip { font-size: .68rem; }
  .brandrow .brand { font-size: 0; gap: 0; }
  .topbar .searchbar { padding: 0 .5rem; gap: .35rem; }
  .searchfocus { display: none; }
  .langsel summary > span { display: none; }
  .langsel summary { padding: .4rem; }
  .statsgrid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dashboardgrid { grid-template-columns: minmax(0, 1fr); }
  .dashboard-side { display: grid; grid-template-columns: minmax(0, 1fr); }
  .row-date { font-size: .65rem; }
  .pagelist li { gap: .4rem; }
  .facetlabel { min-width: 100%; }
  .facetrow .chip { min-height: 2.25rem; }
  .fbrow button, .pageactions .chip, .editactions button, .readform button { min-height: 2.5rem; }
  .main-page .pagehead h1 { font-size: 1.6rem; }
  .prose { font-size: .95rem; }
  .metacard .muted { flex-basis: 100%; overflow-wrap: anywhere; }
  .graphtools { left: .6rem; right: .6rem; top: .6rem; max-width: calc(100% - 1.2rem); gap: .5rem; }
  .graphtools input { width: 100%; }
  .graphhelp { font-size: .65rem; text-align: left; }
  .graphtools { position: relative; margin: .6rem; top: auto; left: auto; right: auto; box-shadow: none; }
  #graph { height: calc(100% - 8rem); min-height: 14rem; }
  .graphstatus { bottom: 2.5rem; }
  .pagecontext { padding-inline: .65rem; }
}
@media (hover: none) { .copybtn { opacity: 1; } }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

{{define "content"}}
<article data-slug="{{.Page.Slug}}" data-read-ref="{{.Page.RelPath}}" {{if and .ReadAvailable (not .Read)}}data-read-secs="{{.ReadSecs}}"{{end}}>
  {{if .TaskReceipt}}<p class="notice">{{t "task_filed_notice"}} <a href="/special/tasks#task-{{.TaskReceipt.ID}}">{{t "nav_tasks"}} · {{.TaskReceiptStatus}}</a></p>{{end}}
  {{if .ReadsPartial}}<p class="notice conflict">{{t "reads_partial"}}</p>{{end}}
  <div class="pagehead"><h1>{{.Page.Title}}</h1></div>
  <div class="metacard">
    <a class="chip" href="/browse?type={{.Page.Type}}">{{.Page.Type}}</a>
    {{range .Page.Tags}}<a class="chip tag" href="/tag/{{.}}">{{.}}</a>{{end}}
    <span class="muted">{{t "page_updated"}} {{.Page.Updated}} · {{.Page.RelPath}}</span>
  </div>
  <div class="pageactions">
    <a class="chip action-primary" href="/edit/{{pathref .Page.RelPath}}">{{t "page_edit"}}</a>
    <form method="post" action="/read/{{pathref .Page.RelPath}}" class="readform" id="readform">
      {{if not .ReadAvailable}}<span class="muted">{{t "read_unavailable"}}</span>{{else if .Read}}
      <span class="chip readmark" title="{{t "page_read_first" "First" .Read.First}}">✓ {{if gt .Read.Count 1}}{{t "page_read_times" "Count" .Read.Count}} {{end}}{{t "page_read_label"}}{{if .ReadAgo}} · {{.ReadAgo}}{{end}}{{if eq .Read.Source "auto"}} <small>{{t "page_auto"}}</small>{{end}}</span>
      <button class="chip" name="action" value="read" title="{{t "page_reread_title"}}">{{t "page_reread"}}</button>
      <button class="chip" name="action" value="unread" title="{{t "page_unread_title"}}">{{t "page_cancel"}}</button>
      {{else}}
      <button class="chip" name="action" value="read" title="{{t "page_read_shortcut"}}">✓ {{t "page_read_button"}}</button>
      {{end}}
    </form>
    <span id="read-status" class="readstatus" role="status" hidden></span>
    {{if .AgentDays}}<span class="muted" title="{{t "page_agent_days_title"}}">🤖 {{t "page_agent_days" "Days" .AgentDays}}</span>{{end}}
  </div>
  <div class="readinglayout">
  <aside class="pagecontext" aria-label="{{t "page_context_label"}}">
    <details class="contextpanel pageoutline" id="pageoutline" data-desktop-open hidden><summary id="toc-title">{{t "page_toc_title"}}</summary><nav aria-labelledby="toc-title"><ol id="page-toc"></ol></nav></details>
  {{if .Suggested}}
  <details class="contextpanel suggested" data-desktop-open>
    <summary>{{t "page_suggested_title"}} <small class="muted">{{t "page_suggested_hint"}}</small></summary>
    <div class="suggestrow">
      {{range .Suggested}}
      <span class="suggestitem">
        <a class="chip suggest" href="{{pageURL .Slug}}" data-slug="{{.Slug}}"
           title="{{t "page_similarity" "Sim" (printf "%.2f" .Sim)}}{{if .Tags}} · {{t "page_tags_shared" "Count" .Tags}}{{end}}">{{.Title}}
          <small>{{printf "%.2f" .Sim}}</small></a>
        {{if .Requested}}<span class="chip reason" title="{{t "task_requested_title"}}">⏳ {{t "task_requested"}}</span>
        {{else}}<form method="post" action="/task/connect" class="inlineform">
          <input type="hidden" name="a" value="{{$.Page.RelPath}}">
          <input type="hidden" name="b" value="{{.Ref}}">
          <input type="hidden" name="sim" value="{{printf "%.2f" .Sim}}">
          <button class="chip" title="{{t "task_connect_title"}}">🔗 {{t "task_connect_button"}}</button>
        </form>{{end}}
      </span>
      {{end}}
    </div>
  </details>
  {{end}}
  <details class="contextpanel tasks" data-desktop-open>
    <summary>{{t "task_section_title"}}{{if .Tasks}} ({{len .Tasks}}){{end}}</summary>
    {{if not .TasksAvailable}}<p class="muted">{{t "home_tasks_unavailable"}}</p>{{end}}
    <p class="muted">{{t "task_section_hint"}} · <a href="/special/tasks">{{t "nav_tasks"}}</a></p>
    {{if .Tasks}}
    <ul class="tasklist">
      {{range .Tasks}}
      <li><span class="chip histkind">{{.TypeLabel}}</span>
        {{if .Other}}<a class="wikilink" href="{{pageURL .Other}}">{{.Other}}</a>{{end}}
        {{if .Request}}{{.Request}}{{end}}
        <span class="chip reason">{{.StatusLabel}}</span>
        <p class="taskmeta muted"><time datetime="{{.Created}}">{{.Created}}</time> · <a href="/special/tasks#task-{{.ID}}">{{t "tasks_receipt_details"}}</a></p>
        {{if .Body}}<details class="proposal"><summary>{{t "tasks_proposal_view"}}</summary><pre>{{.Body}}</pre></details>{{end}}</li>
      {{end}}
    </ul>
    {{end}}
    <details class="taskform">
      <summary class="muted">🤖 {{t "task_edit_summary"}}</summary>
      <form method="post" action="/task/edit/{{pathref .Page.RelPath}}">
        <textarea name="request" rows="3" required aria-label="{{t "task_edit_summary"}}" placeholder="{{t "task_edit_placeholder"}}"></textarea>
        <p><button class="chip">{{t "task_edit_submit"}}</button></p>
      </form>
    </details>
  </details>
  <details class="contextpanel backlinks" data-desktop-open>
    <summary>{{t "page_backlinks_title"}} ({{len .Backlinks}})</summary>
    {{if .Backlinks}}
    <ul>
      {{range .Backlinks}}<li><a class="wikilink" href="{{pageURL .}}">{{.}}</a></li>{{end}}
    </ul>
    {{else}}<p class="muted">{{t "page_none"}}</p>{{end}}
  </details>
    {{if not .SemanticAvailable}}<p class="contextnotice muted">{{t "semantic_unavailable"}}</p>{{end}}
  </aside>
  <div class="readingbody">
  <div class="prose">{{.Body}}</div>
  {{if .GraphNodes}}
  <details class="graph">
    <summary class="muted">{{t "page_local_graph"}} · {{t "page_connections_count" "Count" (len .GraphEdges)}}</summary>
    <svg viewBox="0 0 640 260" role="img" aria-label="{{t "page_graph_label"}}">
      {{range .GraphEdges}}<line x1="{{.X1}}" y1="{{.Y1}}" x2="{{.X2}}" y2="{{.Y2}}"/>{{end}}
      {{range $i, $n := .GraphNodes}}
      <a href="{{pageURL $n.Slug}}"><g>
        <circle cx="{{$n.X}}" cy="{{$n.Y}}" r="{{if eq $i 0}}7{{else}}4{{end}}"
                class="{{if eq $i 0}}center{{else if $n.Missing}}missing{{end}}"/>
        <text x="{{$n.X}}" y="{{$n.Y}}" dy="-9" text-anchor="middle">{{short $n.Slug}}</text>
      </g></a>
      {{end}}
    </svg>
  </details>
  {{end}}
  {{if .AttnRecent}}
  <details class="attn">
    <summary class="muted">{{t "page_access_log"}}{{if .Spark}} <span class="sparkwrap">{{.Spark}}</span>{{end}}</summary>
    <p class="muted attnsum">
      {{if .Read}}{{t "page_read_times_full" "Count" .Read.Count}}{{if .ReadAgo}} ({{t "page_last" "Ago" .ReadAgo}}){{end}}{{else if .ReadAvailable}}{{t "page_not_read"}}{{else}}{{t "read_unavailable"}}{{end}}{{if .AgentDays}} · 🤖 {{t "page_agent_days_full" "Days" .AgentDays}}{{end}}
      · <a href="/history">{{t "page_full_log"}}</a>
    </p>
    <ul class="hist">
      {{range .AttnRecent}}
      <li><span class="histtime muted">{{.Time}}</span> <span class="chip histkind">{{if .Agent}}🤖 {{end}}{{.Label}}</span></li>
      {{end}}
    </ul>
  </details>
  {{end}}
  </div>
  </div>
</article>
{{end}}

