import pathlib,os,json,datetime,hashlib,subprocess,urllib.parse,http.client,socket,time,base64
ROOT=pathlib.Path(__file__).resolve().parent
REPO=pathlib.Path('/Users/nobocop/play/canopy')
ENV=json.loads((ROOT/'environment.json').read_text())
BIN=ROOT/'canopy-lite'
WIKI=ROOT/'Web wiki fixture'
LOG=ROOT/'evidence-work.json'
PROFILE='(version 1) (allow default) (deny file-write* (subpath "/Users/nobocop/go/pkg/mod"))'
def event(kind,**values):
 data=json.loads(LOG.read_text()) if LOG.exists() else {'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'environment':ENV,'root':str(ROOT),'events':[]}
 item={'id':len(data['events'])+1,'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'kind':kind,**values}
 data['events'].append(item);LOG.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps(item,ensure_ascii=False),flush=True)
 return item
def run(argv,cwd=REPO,stdin=None,required=False):
 argv=[str(x) for x in argv];start=time.monotonic()
 p=subprocess.run(argv,cwd=cwd,env=ENV,input=stdin,text=True,capture_output=True)
 event('command',argv=argv,cwd=str(cwd),stdin=stdin,stdout=p.stdout,stderr=p.stderr,exit_code=p.returncode,elapsed_seconds=time.monotonic()-start)
 if required and p.returncode: raise RuntimeError(repr(argv))
 return p
def canopy(*args,required=False):return run([BIN,*args],required=required)
def observe(path):
 p=pathlib.Path(path)
 if not p.exists():return event('observed_file',path=str(p),exists=False)
 b=p.read_bytes();return event('observed_file',path=str(p),exists=True,sha256=hashlib.sha256(b).hexdigest(),content=b.decode('utf-8'),mode=oct(p.stat().st_mode&0o777))
def write(path,content):
 p=pathlib.Path(path);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content);return observe(p)
def hashes(path):
 p=pathlib.Path(path);return {str(q.relative_to(p)):hashlib.sha256(q.read_bytes()).hexdigest() for q in sorted(p.rglob('*')) if q.is_file() and '.git' not in q.parts}
def request(port,path='/',method='GET',body=None,headers=None,timeout=10):
 headers=dict(headers or {});raw=body.encode() if isinstance(body,str) else body
 if raw is not None: headers.setdefault('Content-Length',str(len(raw)))
 c=http.client.HTTPConnection('127.0.0.1',port,timeout=timeout)
 started=time.monotonic()
 try:
  c.request(method,path,body=raw,headers=headers)
  r=c.getresponse();payload=r.read();hs=r.getheaders()
  e=event('http',method=method,connect_host='127.0.0.1',port=port,path=path,request_headers=headers,request_body=(raw.decode('utf-8',errors='replace') if raw is not None else None),status=r.status,response_headers=hs,response_body=payload.decode('utf-8',errors='replace'),response_sha256=hashlib.sha256(payload).hexdigest(),response_bytes=len(payload),elapsed_seconds=time.monotonic()-started)
  return e
 except Exception as ex:
  # An early 413 can interrupt a client still sending a large known body.
  # Read an already available HTTP error response instead of misclassifying it.
  if isinstance(ex,(BrokenPipeError,ConnectionResetError)):
   try:
    r=c.getresponse();payload=r.read();hs=r.getheaders()
    return event('http',method=method,connect_host='127.0.0.1',port=port,path=path,request_headers=headers,request_body=(raw.decode('utf-8',errors='replace') if raw is not None else None),send_interrupted=repr(ex),status=r.status,response_headers=hs,response_body=payload.decode('utf-8',errors='replace'),response_sha256=hashlib.sha256(payload).hexdigest(),response_bytes=len(payload),elapsed_seconds=time.monotonic()-started)
   except Exception as read_ex:
    return event('http_error',method=method,port=port,path=path,request_headers=headers,error=repr(ex),response_read_error=repr(read_ex),request_body_bytes=len(raw or b''),elapsed_seconds=time.monotonic()-started)
  return event('http_error',method=method,port=port,path=path,request_headers=headers,error=repr(ex),elapsed_seconds=time.monotonic()-started)
 finally:c.close()
def free_port():
 with socket.socket() as s:s.bind(('127.0.0.1',0));return s.getsockname()[1]
def start_server(addr_host='127.0.0.1',allow_hosts=None,label='local'):
 port=free_port();addr=addr_host+':'+str(port)
 argv=[str(BIN),'serve','--addr',addr,'--wiki',str(WIKI)]
 for h in allow_hosts or []:argv+=['--allow-host',h]
 out=ROOT/(label+'-server.stdout');err=ROOT/(label+'-server.stderr')
 with out.open('wb') as a,err.open('wb') as b:
  p=subprocess.Popen(argv,cwd=REPO,env=ENV,stdout=a,stderr=b)
 event('server_start',argv=argv,cwd=str(REPO),pid=p.pid,port=port,label=label)
 for _ in range(100):
  if p.poll() is not None:raise RuntimeError(err.read_text())
  try:
   with socket.create_connection(('127.0.0.1',port),.1):break
  except OSError:time.sleep(.05)
 else:raise RuntimeError('server start timeout')
 return p,port,out,err
def stop_server(server):
 p,port,out,err=server
 p.terminate()
 try:code=p.wait(5)
 except subprocess.TimeoutExpired:p.kill();code=p.wait(5)
 event('server_stop',pid=p.pid,port=port,exit_code=code,stdout=out.read_text(),stderr=err.read_text())
def form(data):return urllib.parse.urlencode(data)

