from lab import *
from html.parser import HTMLParser
import re
class Prose(HTMLParser):
 def __init__(self):super().__init__();self.depth=0;self.code=0;self.links=[];self.code_text=[];self.scripts=[];self.unsafe=[]
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if tag=='div' and a.get('class')=='prose':self.depth=1;return
  if self.depth:
   if tag not in ('br','hr','img','input','meta','link'):self.depth+=1
   if tag in ('pre','code'):self.code+=1
   if tag=='a':self.links.append({'attributes':a,'inside_code':self.code>0})
   if tag=='script':self.scripts.append(a)
   if tag in ('iframe','img','object','svg') or any(k.lower().startswith('on') for k in a):self.unsafe.append({'tag':tag,'attrs':a})
 def handle_endtag(self,tag):
  if self.depth:
