		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() {
			return nil
		}
		data, err := assets.ReadFile(path)
		if err != nil {
			return err
		}
		s.staticTags["/"+path] = `"` + contentHash(data) + `"`
		return nil
